package com.moneymaker;

/** Whether the plugin treats you as an ironman. */
public enum IronmanMode
{
	AUTO("Detect from account"),
	ON("On"),
	OFF("Off");

	private final String label;

	IronmanMode(String label)
	{
		this.label = label;
	}

	@Override
	public String toString()
	{
		return label;
	}
}

package com.moneymaker;

import com.moneymaker.data.PriceMode;
import net.runelite.client.config.Config;
import net.runelite.client.config.ConfigGroup;
import net.runelite.client.config.ConfigItem;
import net.runelite.client.config.Range;
import net.runelite.client.config.Units;

@ConfigGroup(MoneyMakerConfig.GROUP)
public interface MoneyMakerConfig extends Config
{
	String GROUP = "moneymaker";

	@ConfigItem(
		keyName = "priceMode",
		name = "Prices",
		description = "Instant: buy and sell straight away (safest). Average: last hour's average. "
			+ "Patient: place offers and wait (most profit, slowest).",
		position = 0
	)
	default PriceMode priceMode()
	{
		return PriceMode.INSTANT;
	}

	@Range(min = 10, max = 300)
	@Units(Units.PERCENT)
	@ConfigItem(
		keyName = "speed",
		name = "Your speed",
		description = "Scale the actions-per-hour estimates to how fast you play",
		position = 1
	)
	default int speed()
	{
		return 100;
	}

	@ConfigItem(
		keyName = "onlyDoable",
		name = "Only jobs I can do",
		description = "Hide jobs above your current level (needs you to be logged in)",
		position = 2
	)
	default boolean onlyDoable()
	{
		return false;
	}

	@ConfigItem(
		keyName = "includeMembers",
		name = "Include members jobs",
		description = "Show members-only jobs",
		position = 3
	)
	default boolean includeMembers()
	{
		return true;
	}

	@ConfigItem(
		keyName = "hideLowVolume",
		name = "Hide low-volume jobs",
		description = "Hide jobs whose product trades less per hour than you'd make, or whose price is over a day old",
		position = 4
	)
	default boolean hideLowVolume()
	{
		return false;
	}

	@Range(min = 1, max = 60)
	@Units(Units.MINUTES)
	@ConfigItem(
		keyName = "refreshMinutes",
		name = "Price refresh",
		description = "How often to download prices from the OSRS Wiki price API (prices.runescape.wiki). "
			+ "Only price requests are sent, nothing about your account",
		position = 5
	)
	default int refreshMinutes()
	{
		return 5;
	}

	@ConfigItem(
		keyName = "farmNotify",
		name = "Farm run alerts",
		description = "Send a notification when a farm run, bird house or daily timer is ready",
		position = 6
	)
	default boolean farmNotify()
	{
		return true;
	}

	@ConfigItem(
		keyName = "ironman",
		name = "Ironman mode",
		description = "Detect from account: on for ironman, hardcore, ultimate and group ironman accounts. "
			+ "Train tab shows what to gather instead of what to buy, and opens first",
		position = 7
	)
	default IronmanMode ironman()
	{
		return IronmanMode.AUTO;
	}
}

package com.moneymaker;

import com.google.inject.Provides;
import com.moneymaker.data.BossCheck;
import com.moneymaker.data.BossQuests;
import com.moneymaker.data.BossSetup;
import com.moneymaker.data.FarmRoute;
import com.moneymaker.data.FarmRun;
import com.moneymaker.data.Gear;
import com.moneymaker.data.Training;
import com.moneymaker.data.GearPricer;
import com.moneymaker.data.ItemPrice;
import com.moneymaker.data.PriceBook;
import com.moneymaker.data.Recipe;
import com.moneymaker.data.WikiPriceClient;
import com.moneymaker.ui.MoneyMakerPanel;
import java.awt.Color;
import java.awt.Font;
import java.awt.Graphics2D;
import java.awt.RenderingHints;
import java.awt.image.BufferedImage;
import java.io.IOException;
import java.io.InputStream;
import java.util.Collections;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import java.util.Set;
import java.util.concurrent.ScheduledExecutorService;
import java.util.concurrent.ScheduledFuture;
import java.util.concurrent.TimeUnit;
import java.util.function.Consumer;
import javax.inject.Inject;
import javax.swing.SwingUtilities;
import net.runelite.api.Client;
import net.runelite.api.Experience;
import net.runelite.api.GameState;
import net.runelite.api.Item;
import net.runelite.api.ItemContainer;
import net.runelite.api.Quest;
import net.runelite.api.QuestState;
import net.runelite.api.Skill;
import net.runelite.api.events.GameStateChanged;
import net.runelite.api.events.GameTick;
import net.runelite.api.events.ItemContainerChanged;
import net.runelite.api.gameval.InventoryID;
import net.runelite.api.gameval.VarbitID;
import net.runelite.client.Notifier;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.events.ConfigChanged;
import net.runelite.client.game.ItemManager;
import net.runelite.client.plugins.Plugin;
import net.runelite.client.plugins.PluginDescriptor;
import net.runelite.client.ui.ClientToolbar;
import net.runelite.client.ui.NavigationButton;
import org.slf4j.Logger;
import org.slf4j.LoggerFactory;

@PluginDescriptor(
	name = "Adventurer's Ledger",
	description = "Money makers, fastest training routes, farm run timers and boss gear at live GE prices",
	tags = {"money", "gp", "profit", "xp", "training", "ironman", "farming", "timers", "boss", "gear", "ledger"}
)
public class MoneyMakerPlugin extends Plugin
{
	private static final Logger log = LoggerFactory.getLogger(MoneyMakerPlugin.class);

	@Inject
	private Client client;
	@Inject
	private ClientToolbar clientToolbar;
	@Inject
	private MoneyMakerConfig config;
	@Inject
	private ItemManager itemManager;
	@Inject
	private ScheduledExecutorService executor;
	@Inject
	private WikiPriceClient wiki;
	@Inject
	private ConfigManager configManager;
	@Inject
	private Notifier notifier;

	private MoneyMakerPanel panel;
	private NavigationButton navButton;
	private ScheduledFuture<?> priceTask;
	private ScheduledFuture<?> farmTask;
	/** Bank save waiting to be written, so a busy bank session writes once, not on every change. */
	private ScheduledFuture<?> bankSaveTask;
	private volatile Runnable pendingBankSave;
	/** Account the farm timers belong to (the last one logged in). 0 until an account has been seen. */
	private volatile long farmAccount;
	private volatile List<FarmRun> farmRuns = Collections.emptyList();
	private volatile FarmRoute farmRoute = FarmRoute.empty();
	private volatile BossQuests bossQuests = BossQuests.empty();
	private volatile BossCheck bossCheck = BossCheck.empty();
	/** Quest name to how far you are with it, for the quests bosses need. Empty when logged out. */
	private volatile Map<String, QuestState> questStates = Collections.emptyMap();
	/** Game ticks until quest progress is checked again. */
	private int questCheckIn;
	private volatile Training training = Training.empty();
	private volatile Gear gear = Gear.empty();
	/** Item id -> quantity in your inventory, worn equipment and bank (unnoted ids). */
	private volatile Map<Integer, Long> invItems = Collections.emptyMap();
	private volatile Map<Integer, Long> wornItems = Collections.emptyMap();
	private volatile Map<Integer, Long> bankItems = Collections.emptyMap();
	private volatile boolean bankSeen;
	private final Map<Integer, String> itemNames = new java.util.concurrent.ConcurrentHashMap<>();
	/** Account type varbit: 0 normal, anything else is an ironman type. -1 when unknown. */
	private volatile int accountType = -1;
	private long loadedBankFor;

	private volatile List<Recipe> recipes = Collections.emptyList();
	private volatile List<BossSetup> bosses = Collections.emptyList();
	private volatile GearPricer gearPricer = new GearPricer(Collections.emptyMap());
	private volatile PriceBook prices = PriceBook.EMPTY;
	private volatile String priceError;
	private volatile List<WikiPriceClient.Mapping> mapping = Collections.emptyList();
	/** Skill name -> {level, xp}. Empty when logged out. */
	private volatile Map<String, long[]> skills = Collections.emptyMap();

	@Provides
	MoneyMakerConfig provideConfig(ConfigManager configManager)
	{
		return configManager.getConfig(MoneyMakerConfig.class);
	}

	@Override
	protected void startUp()
	{
		// each file loads on its own, so a problem in one doesn't take the others down with it
		recipes = load("recipes.txt", Recipe::load, Collections.emptyList());
		bosses = load("bosses.txt", BossSetup::load, Collections.emptyList());
		gearPricer = load("aliases.txt", GearPricer::load, new GearPricer(Collections.emptyMap()));
		farmRuns = load("farmruns.txt", FarmRun::load, Collections.emptyList());
		farmRoute = load("farmroutes.txt", FarmRoute::load, FarmRoute.empty());
		bossQuests = load("bossquests.txt", in ->
		{
			try (InputStream lines = resource("questlines.txt"))
			{
				return BossQuests.load(in, lines);
			}
		}, BossQuests.empty());
		training = load("training.txt", Training::load, Training.empty());
		gear = load("gear.txt", Gear::load, Gear.empty());
		bossCheck = load("bossskills.txt", BossCheck::load, BossCheck.empty());
		farmAccount = savedFarmAccount();

		panel = new MoneyMakerPanel(this, itemManager);
		navButton = NavigationButton.builder()
			.tooltip("Adventurer's Ledger")
			.icon(createIcon())
			.priority(7)
			.panel(panel)
			.build();
		clientToolbar.addNavigation(navButton);
		schedulePriceRefresh();
		farmTask = executor.scheduleWithFixedDelay(this::checkFarmTimers, 5, 30, TimeUnit.SECONDS);
	}

	@Override
	protected void shutDown()
	{
		if (priceTask != null)
		{
			priceTask.cancel(false);
		}
		if (farmTask != null)
		{
			farmTask.cancel(false);
		}
		if (bankSaveTask != null)
		{
			bankSaveTask.cancel(false);
		}
		Runnable save = pendingBankSave;
		if (save != null)
		{
			save.run();
		}
		clientToolbar.removeNavigation(navButton);
		if (panel != null)
		{
			panel.shutDown();
		}
		panel = null;
		skills = Collections.emptyMap();
	}

	private interface Loader<T>
	{
		T load(InputStream in) throws IOException;
	}

	/** Load one data file, falling back to an empty value (and logging why) if it can't be read. */
	private <T> T load(String name, Loader<T> loader, T fallback)
	{
		try (InputStream in = resource(name))
		{
			return loader.load(in);
		}
		catch (IOException | RuntimeException e)
		{
			log.error("Adventurer's Ledger couldn't load {}", name, e);
			return fallback;
		}
	}

	private InputStream resource(String name) throws IOException
	{
		InputStream in = MoneyMakerPlugin.class.getResourceAsStream(name);
		if (in == null)
		{
			throw new IOException("Missing resource " + name);
		}
		return in;
	}

	// ---------------------------------------------------------------- events

	@Subscribe
	public void onGameTick(GameTick tick)
	{
		if (client.getGameState() != GameState.LOGGED_IN)
		{
			return;
		}
		accountType = client.getVarbitValue(VarbitID.IRONMAN);
		loadSavedBank();
		claimFarmTimers();
		checkQuests();
		resolveNames();

		Map<String, long[]> now = new HashMap<>();
		for (Skill s : Skill.values())
		{
			if (!"OVERALL".equals(s.name()))
			{
				now.put(s.name(), new long[]{client.getRealSkillLevel(s), client.getSkillExperience(s)});
			}
		}
		if (!sameSkills(now, skills))
		{
			skills = Collections.unmodifiableMap(now);
			updatePanel(MoneyMakerPanel::refreshJobs);
		}
	}

	/** Logging out: forget the levels and items of the account that just left. */
	@Subscribe
	public void onGameStateChanged(GameStateChanged event)
	{
		if (event.getGameState() != GameState.LOGIN_SCREEN || skills.isEmpty())
		{
			return;
		}
		skills = Collections.emptyMap();
		questStates = Collections.emptyMap();
		questCheckIn = 0;
		accountType = -1;
		invItems = Collections.emptyMap();
		wornItems = Collections.emptyMap();
		updatePanel(MoneyMakerPanel::refreshAll);
	}

	/** How often to re-read quest progress, in game ticks (about 30 seconds). */
	private static final int QUEST_CHECK_TICKS = 50;

	/** Read how far you are with the quests bosses need (client thread only). */
	private void checkQuests()
	{
		if (questCheckIn-- > 0)
		{
			return;
		}
		questCheckIn = QUEST_CHECK_TICKS;
		Set<String> wanted = bossQuests.allQuests();
		if (wanted.isEmpty())
		{
			return;
		}
		Map<String, QuestState> now = new HashMap<>();
		for (Quest q : Quest.values())
		{
			if (wanted.contains(q.getName()))
			{
				now.put(q.getName(), q.getState(client));
			}
		}
		if (!now.equals(questStates))
		{
			questStates = Collections.unmodifiableMap(now);
			updatePanel(MoneyMakerPanel::refreshBosses);
		}
	}

	/** Skill levels each boss needs. */
	public BossCheck getBossCheck()
	{
		return bossCheck;
	}

	/** True when you have every level a job needs. Also true when logged out, as there's nothing to check against. */
	public boolean meetsReqs(Recipe r)
	{
		for (Recipe.Req q : r.getReqs())
		{
			long[] have = getSkill(q.getSkill());
			if (have != null && have[0] < q.getLevel())
			{
				return false;
			}
		}
		return true;
	}

	/** Open the Goal tab with this item as the thing to save for. */
	public void planFor(String item)
	{
		updatePanel(p -> p.showGoal(item));
	}

	/** A small value the panel wants remembered between sessions (your goal), or null. */
	public String getSaved(String key)
	{
		return configManager == null ? null : configManager.getConfiguration(MoneyMakerConfig.GROUP, key);
	}

	/** Remember a value between sessions; null forgets it. */
	public void save(String key, String value)
	{
		if (configManager == null)
		{
			return;
		}
		if (value == null)
		{
			configManager.unsetConfiguration(MoneyMakerConfig.GROUP, key);
		}
		else
		{
			configManager.setConfiguration(MoneyMakerConfig.GROUP, key, value);
		}
	}

	public BossQuests getBossQuests()
	{
		return bossQuests;
	}

	/** How far you are with a quest, or null when logged out or the quest isn't known. */
	public QuestState getQuestState(String quest)
	{
		return questStates.get(quest);
	}

	private static boolean sameSkills(Map<String, long[]> a, Map<String, long[]> b)
	{
		if (a.size() != b.size())
		{
			return false;
		}
		for (Map.Entry<String, long[]> e : a.entrySet())
		{
			long[] o = b.get(e.getKey());
			if (o == null || o[0] != e.getValue()[0] || o[1] != e.getValue()[1])
			{
				return false;
			}
		}
		return true;
	}

	@Subscribe
	public void onConfigChanged(ConfigChanged event)
	{
		if (!MoneyMakerConfig.GROUP.equals(event.getGroup()))
		{
			return;
		}
		// things the plugin saves for itself (goal, timers, bank) aren't settings: nothing to redraw
		String key = event.getKey();
		if (key.startsWith("goal") || key.startsWith("farm_") || key.startsWith("farmdone_") || key.equals("farmAccount")
			|| key.startsWith("bank_"))
		{
			return;
		}
		if ("refreshMinutes".equals(event.getKey()))
		{
			schedulePriceRefresh();
		}
		updatePanel(MoneyMakerPanel::refreshAll);
	}

	// ---------------------------------------------------------------- prices

	private void schedulePriceRefresh()
	{
		if (priceTask != null)
		{
			priceTask.cancel(false);
		}
		priceTask = executor.scheduleWithFixedDelay(this::refreshPrices, 0, config.refreshMinutes(), TimeUnit.MINUTES);
	}

	public void refreshPricesNow()
	{
		executor.execute(this::refreshPrices);
	}

	private void refreshPrices()
	{
		try
		{
			if (mapping.isEmpty())
			{
				mapping = wiki.fetchMapping();
			}
			Map<Integer, WikiPriceClient.Latest> latest = wiki.fetchLatest();
			Map<Integer, WikiPriceClient.Average> hourly = wiki.fetchHourly();

			Map<String, ItemPrice> byName = new HashMap<>();
			for (WikiPriceClient.Mapping m : mapping)
			{
				if (m.name == null)
				{
					continue;
				}
				WikiPriceClient.Latest l = latest.get(m.id);
				WikiPriceClient.Average h = hourly.get(m.id);
				byName.put(PriceBook.key(m.name), new ItemPrice(m.id, m.name, m.limit == null ? 0 : m.limit,
					l == null ? 0 : nz(l.high), l == null ? 0 : nz(l.low),
					h == null ? 0 : nz(h.avgHighPrice), h == null ? 0 : nz(h.avgLowPrice),
					h == null ? 0 : nz(h.highPriceVolume) + nz(h.lowPriceVolume),
					l == null ? 0 : Math.max(nz(l.highTime), nz(l.lowTime))));
			}
			prices = new PriceBook(Collections.unmodifiableMap(byName), System.currentTimeMillis());
			priceError = null;
		}
		catch (Exception e)
		{
			log.warn("Adventurer's Ledger couldn't fetch prices", e);
			priceError = e.getMessage() == null ? e.getClass().getSimpleName() : e.getMessage();
		}
		updatePanel(MoneyMakerPanel::refreshAll);
	}

	private static long nz(Long v)
	{
		return v == null ? 0 : v;
	}

	// ---------------------------------------------------------------- farm run timers

	// ---------------------------------------------------------------- items you own

	private static final int INVENTORY = InventoryID.INV;
	private static final int EQUIPMENT = InventoryID.WORN;
	private static final int BANK = InventoryID.BANK;
	private static final int BANK_SAVE_DELAY_SECONDS = 3;

	@Subscribe
	public void onItemContainerChanged(ItemContainerChanged event)
	{
		int id = event.getContainerId();
		if (id != INVENTORY && id != EQUIPMENT && id != BANK)
		{
			return;
		}
		ItemContainer c = event.getItemContainer();
		if (c == null)
		{
			return;
		}
		Map<Integer, Long> items = new HashMap<>();
		for (Item it : c.getItems())
		{
			if (it.getId() <= 0 || it.getQuantity() <= 0)
			{
				continue;
			}
			items.merge(itemManager.canonicalize(it.getId()), (long) it.getQuantity(), Long::sum);
		}
		Map<Integer, Long> frozen = Collections.unmodifiableMap(items);
		if (id == INVENTORY)
		{
			invItems = frozen;
		}
		else if (id == EQUIPMENT)
		{
			wornItems = frozen;
		}
		else
		{
			bankItems = frozen;
			bankSeen = true;
			saveBank(frozen);
		}
		resolveNames();
		updatePanel(MoneyMakerPanel::refreshTrain);
	}

	/** Remember the bank between sessions (only item ids and amounts, in your RuneLite profile). */
	private void saveBank(Map<Integer, Long> items)
	{
		long hash = client.getAccountHash();
		if (hash == -1)
		{
			return;
		}
		// the bank changes with every deposit and withdrawal; wait for it to settle, then write once
		Runnable save = () ->
		{
			pendingBankSave = null;
			StringBuilder sb = new StringBuilder();
			for (Map.Entry<Integer, Long> e : items.entrySet())
			{
				sb.append(sb.length() > 0 ? "," : "").append(e.getKey()).append(':').append(e.getValue());
			}
			configManager.setConfiguration(MoneyMakerConfig.GROUP, "bank_" + hash, sb.toString());
		};
		if (bankSaveTask != null)
		{
			bankSaveTask.cancel(false);
		}
		pendingBankSave = save;
		bankSaveTask = executor.schedule(save, BANK_SAVE_DELAY_SECONDS, TimeUnit.SECONDS);
	}

	private void loadSavedBank()
	{
		long hash = client.getAccountHash();
		if (hash == -1 || hash == loadedBankFor)
		{
			return;
		}
		// new account (or first login): forget the old bank, then load this account's saved one
		boolean switched = loadedBankFor != 0;
		loadedBankFor = hash;
		if (switched || !bankSeen)
		{
			bankItems = Collections.emptyMap();
			bankSeen = false;
		}
		String saved = configManager.getConfiguration(MoneyMakerConfig.GROUP, "bank_" + hash);
		if (saved == null || saved.isEmpty())
		{
			return;
		}
		Map<Integer, Long> items = new HashMap<>();
		for (String part : saved.split(","))
		{
			int colon = part.indexOf(':');
			try
			{
				items.put(Integer.parseInt(part.substring(0, colon)), Long.parseLong(part.substring(colon + 1)));
			}
			catch (RuntimeException ignored)
			{
			}
		}
		bankItems = Collections.unmodifiableMap(items);
		bankSeen = true;
		updatePanel(MoneyMakerPanel::refreshTrain);
	}

	/** Look up names for item ids (client thread only). */
	private void resolveNames()
	{
		int budget = 300;
		for (Map<Integer, Long> m : java.util.Arrays.asList(invItems, wornItems, bankItems))
		{
			for (Integer id : m.keySet())
			{
				if (budget > 0 && !itemNames.containsKey(id))
				{
					budget--;
					itemNames.put(id, itemManager.getItemComposition(id).getName());
				}
			}
		}
	}

	/** Everything you own by lower-case name, with where it is. */
	public Map<String, Gear.Owned> getOwned()
	{
		Map<String, Gear.Owned> out = new HashMap<>();
		String[] where = {"worn", "bag", "bank"};
		List<Map<Integer, Long>> maps = java.util.Arrays.asList(wornItems, invItems, bankItems);
		for (int i = 0; i < maps.size(); i++)
		{
			for (Map.Entry<Integer, Long> e : maps.get(i).entrySet())
			{
				String name = itemNames.get(e.getKey());
				if (name == null || name.equalsIgnoreCase("null"))
				{
					continue;
				}
				String key = name.toLowerCase(java.util.Locale.ROOT);
				Gear.Owned prev = out.get(key);
				out.put(key, new Gear.Owned(name, e.getValue() + (prev == null ? 0 : prev.getQty()),
					prev == null ? where[i] : prev.getWhere()));
			}
		}
		return out;
	}

	public boolean isBankSeen()
	{
		return bankSeen;
	}

	public Gear getGear()
	{
		return gear;
	}

	/** Ironman mode from the setting, or from your account type when set to detect. */
	public boolean isIronman()
	{
		switch (config.ironman())
		{
			case ON:
				return true;
			case OFF:
				return false;
			default:
				return accountType > 0;
		}
	}

	public Training getTraining()
	{
		return training;
	}

	/** Where to go on each farm run. */
	public FarmRoute getFarmRoute()
	{
		return farmRoute;
	}

	public List<FarmRun> getFarmRuns()
	{
		return farmRuns;
	}

	/** When this run was planted (epoch ms), or 0 if no timer is running. Saved in your RuneLite profile. */
	public long getPlanted(FarmRun run)
	{
		String v = configManager.getConfiguration(MoneyMakerConfig.GROUP, farmKey("farm_", run));
		try
		{
			return v == null ? 0 : Long.parseLong(v);
		}
		catch (NumberFormatException e)
		{
			return 0;
		}
	}

	/** When this run will be ready (epoch ms), or 0 if no timer is running. */
	public long getReadyAt(FarmRun run)
	{
		long planted = getPlanted(run);
		return planted == 0 ? 0 : planted + Math.round(run.getGrowMinutes() * 60_000);
	}

	public void startFarmTimer(FarmRun run)
	{
		configManager.setConfiguration(MoneyMakerConfig.GROUP, farmKey("farm_", run), String.valueOf(System.currentTimeMillis()));
		configManager.unsetConfiguration(MoneyMakerConfig.GROUP, farmKey("farmdone_", run));
		updatePanel(MoneyMakerPanel::refreshFarm);
	}

	public void clearFarmTimer(FarmRun run)
	{
		configManager.unsetConfiguration(MoneyMakerConfig.GROUP, farmKey("farm_", run));
		configManager.unsetConfiguration(MoneyMakerConfig.GROUP, farmKey("farmdone_", run));
		updatePanel(MoneyMakerPanel::refreshFarm);
	}

	/**
	 * Config key for a run's timer. Timers belong to the account that was last logged in, so two
	 * accounts don't share them; they keep counting (and alerting) on the login screen.
	 */
	private String farmKey(String prefix, FarmRun run)
	{
		long account = farmAccount;
		return account == 0 ? prefix + run.getId() : prefix + account + "_" + run.getId();
	}

	private long savedFarmAccount()
	{
		String v = configManager.getConfiguration(MoneyMakerConfig.GROUP, "farmAccount");
		try
		{
			return v == null ? 0 : Long.parseLong(v);
		}
		catch (NumberFormatException e)
		{
			return 0;
		}
	}

	/** On login, point the farm timers at this account. Timers set before accounts were tracked move to it. */
	private void claimFarmTimers()
	{
		long hash = client.getAccountHash();
		if (hash == -1 || hash == 0 || hash == farmAccount)
		{
			return;
		}
		for (FarmRun run : farmRuns)
		{
			for (String prefix : new String[]{"farm_", "farmdone_"})
			{
				String oldKey = prefix + run.getId();
				String newKey = prefix + hash + "_" + run.getId();
				String old = configManager.getConfiguration(MoneyMakerConfig.GROUP, oldKey);
				if (old == null)
				{
					continue;
				}
				if (configManager.getConfiguration(MoneyMakerConfig.GROUP, newKey) == null)
				{
					configManager.setConfiguration(MoneyMakerConfig.GROUP, newKey, old);
				}
				configManager.unsetConfiguration(MoneyMakerConfig.GROUP, oldKey);
			}
		}
		farmAccount = hash;
		configManager.setConfiguration(MoneyMakerConfig.GROUP, "farmAccount", String.valueOf(hash));
		updatePanel(MoneyMakerPanel::refreshFarm);
	}

	private void checkFarmTimers()
	{
		long now = System.currentTimeMillis();
		for (FarmRun run : farmRuns)
		{
			long ready = getReadyAt(run);
			if (ready == 0 || now < ready)
			{
				continue;
			}
			String doneKey = farmKey("farmdone_", run);
			if (configManager.getConfiguration(MoneyMakerConfig.GROUP, doneKey) == null)
			{
				configManager.setConfiguration(MoneyMakerConfig.GROUP, doneKey, "1");
				if (config.farmNotify())
				{
					notifier.notify("Adventurer's Ledger: " + run.getName() + " is ready");
				}
			}
		}
		updatePanel(MoneyMakerPanel::refreshFarmTimers);
	}

	// ---------------------------------------------------------------- for the panel

	public MoneyMakerConfig getConfig()
	{
		return config;
	}

	public List<Recipe> getRecipes()
	{
		return recipes;
	}

	public List<BossSetup> getBosses()
	{
		return bosses;
	}

	public GearPricer getGearPricer()
	{
		return gearPricer;
	}

	public PriceBook getPrices()
	{
		return prices;
	}

	public String getPriceError()
	{
		return priceError;
	}

	/** {level, xp} for a skill, or null if not logged in. */
	public boolean isLoggedIn()
	{
		return !skills.isEmpty();
	}

	/** Level and xp in a skill, or null when logged out. "MELEE" means your lowest of Attack, Strength and Defence. */
	public long[] getSkill(String skill)
	{
		return skills.get(resolveSkill(skill));
	}

	/** Which real skill a job trains: "MELEE" becomes the lowest melee skill (the one you'd train next). */
	public String resolveSkill(String skill)
	{
		if (!"MELEE".equals(skill))
		{
			return skill;
		}
		String best = "ATTACK";
		long bestXp = Long.MAX_VALUE;
		for (String s : new String[]{"ATTACK", "STRENGTH", "DEFENCE"})
		{
			long[] v = skills.get(s);
			if (v != null && v[1] < bestXp)
			{
				best = s;
				bestXp = v[1];
			}
		}
		return skills.isEmpty() ? skill : best;
	}

	/** XP needed to reach the level after `level`, or -1. */
	public static long xpForNextLevel(long level)
	{
		if (level < 1 || level >= 99)
		{
			return -1;
		}
		return Experience.getXpForLevel((int) level + 1);
	}

	private void updatePanel(Consumer<MoneyMakerPanel> action)
	{
		SwingUtilities.invokeLater(() ->
		{
			MoneyMakerPanel p = panel;
			if (p != null)
			{
				action.accept(p);
			}
		});
	}

	private static BufferedImage createIcon()
	{
		BufferedImage img = new BufferedImage(16, 16, BufferedImage.TYPE_INT_ARGB);
		Graphics2D g = img.createGraphics();
		g.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);
		g.setRenderingHint(RenderingHints.KEY_TEXT_ANTIALIASING, RenderingHints.VALUE_TEXT_ANTIALIAS_ON);
		g.setColor(new Color(0x2E7D32));
		g.fillRoundRect(1, 3, 14, 10, 3, 3);
		g.setColor(new Color(0x1B5E20));
		g.drawRoundRect(1, 3, 14, 10, 3, 3);
		g.setColor(new Color(0xE8F5E9));
		g.setFont(new Font(Font.SANS_SERIF, Font.BOLD, 10));
		g.drawString("$", 5, 12);
		g.dispose();
		return img;
	}
}

package com.moneymaker.data;

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStream;
import java.io.InputStreamReader;
import java.nio.charset.StandardCharsets;
import java.util.ArrayList;
import java.util.Collections;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;

/**
 * "Can I fight this boss?": the skill levels a boss needs (bossskills.txt) and which of its gear
 * you already own.
 */
public class BossCheck
{
	private final Map<String, List<SkillReq>> skills;

	private BossCheck(Map<String, List<SkillReq>> skills)
	{
		this.skills = skills;
	}

	public static BossCheck empty()
	{
		return new BossCheck(Collections.emptyMap());
	}

	/** Skill levels needed for a boss. Empty when it needs none. */
	public List<SkillReq> skillsFor(String boss)
	{
		return skills.getOrDefault(boss, Collections.emptyList());
	}

	public Map<String, List<SkillReq>> all()
	{
		return skills;
	}

	/** A skill level a boss needs. */
	public static class SkillReq
	{
		private final String skill;
		private final int level;
		private final String note;

		SkillReq(String skill, int level, String note)
		{
			this.skill = skill;
			this.level = level;
			this.note = note;
		}

		public String getSkill()
		{
			return skill;
		}

		public int getLevel()
		{
			return level;
		}

		public String getNote()
		{
			return note;
		}
	}

	/** Parse bossskills.txt: boss|SKILL|level|note */
	public static BossCheck load(InputStream in) throws IOException
	{
		Map<String, List<SkillReq>> map = new LinkedHashMap<>();
		try (BufferedReader r = new BufferedReader(new InputStreamReader(in, StandardCharsets.UTF_8)))
		{
			String line;
			while ((line = r.readLine()) != null)
			{
				line = line.trim();
				if (line.isEmpty() || line.startsWith("#"))
				{
					continue;
				}
				String[] f = line.split("\\|", -1);
				if (f.length < 3)
				{
					continue;
				}
				int level;
				try
				{
					level = Integer.parseInt(f[2].trim());
				}
				catch (NumberFormatException e)
				{
					continue;
				}
				map.computeIfAbsent(f[0].trim(), k -> new ArrayList<>())
					.add(new SkillReq(f[1].trim(), level, f.length > 3 ? f[3].trim() : ""));
			}
		}
		for (Map.Entry<String, List<SkillReq>> e : map.entrySet())
		{
			e.setValue(Collections.unmodifiableList(e.getValue()));
		}
		return new BossCheck(map);
	}

	// ---------------------------------------------------------------- gear you own

	/**
	 * Whether you own a gear option, and where. "A + B" (used together) counts only if you own
	 * every part. Returns null if you don't.
	 */
	public static Gear.Owned owned(String option, Map<String, Gear.Owned> have)
	{
		if (have == null || have.isEmpty())
		{
			return null;
		}
		Gear.Owned first = null;
		for (String part : option.split(" \\+ "))
		{
			Gear.Owned o = Gear.find(have, part.trim());
			if (o == null)
			{
				return null;
			}
			if (first == null)
			{
				first = o;
			}
		}
		return first;
	}

	/** Any option in a tier that you own, or null. */
	public static Gear.Owned ownedInTier(List<String> tier, Map<String, Gear.Owned> have)
	{
		for (String option : tier)
		{
			Gear.Owned o = owned(option, have);
			if (o != null)
			{
				return o;
			}
		}
		return null;
	}

	/** How your gear stacks up for one boss set-up. */
	public static class Kit
	{
		private final int slots;
		private final int slotsOwned;
		private final long costToFill;
		private final List<String> toBuy;
		private final List<String> toEarn;

		Kit(int slots, int slotsOwned, long costToFill, List<String> toBuy, List<String> toEarn)
		{
			this.slots = slots;
			this.slotsOwned = slotsOwned;
			this.costToFill = costToFill;
			this.toBuy = toBuy;
			this.toEarn = toEarn;
		}

		public int getSlots()
		{
			return slots;
		}

		/** Slots where you own at least one of the listed options. */
		public int getSlotsOwned()
		{
			return slotsOwned;
		}

		/** GE cost of the cheapest option for every slot you own nothing for. */
		public long getCostToFill()
		{
			return costToFill;
		}

		/** The cheapest option to buy for each empty slot. */
		public List<String> getToBuy()
		{
			return toBuy;
		}

		/** Empty slots where nothing listed can be bought (untradeable gear to earn). */
		public List<String> getToEarn()
		{
			return toEarn;
		}
	}

	/** Compare a set-up with what you own: how many slots are covered and what the rest would cost. */
	public static Kit kit(BossSetup setup, GearPricer pricer, PriceBook prices, Map<String, Gear.Owned> have)
	{
		int ownedSlots = 0;
		long cost = 0;
		List<String> toBuy = new ArrayList<>();
		List<String> toEarn = new ArrayList<>();
		for (BossSetup.Slot slot : setup.getSlots())
		{
			boolean covered = false;
			GearPricer.Price cheapest = null;
			for (List<String> tier : slot.getTiers())
			{
				if (ownedInTier(tier, have) != null)
				{
					covered = true;
					break;
				}
				GearPricer.Price p = pricer.cheapestOf(tier, prices);
				if (p != null && p.isTradeable() && (cheapest == null || p.getCost() < cheapest.getCost()))
				{
					cheapest = p;
				}
			}
			if (covered)
			{
				ownedSlots++;
			}
			else if (cheapest != null)
			{
				cost += cheapest.getCost();
				toBuy.add(cheapest.getName());
			}
			else
			{
				toEarn.add(slot.getName());
			}
		}
		return new Kit(setup.getSlots().size(), ownedSlots, cost,
			Collections.unmodifiableList(toBuy), Collections.unmodifiableList(toEarn));
	}
}

package com.moneymaker.data;

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStream;
import java.io.InputStreamReader;
import java.nio.charset.StandardCharsets;
import java.util.ArrayList;
import java.util.Collections;
import java.util.LinkedHashMap;
import java.util.LinkedHashSet;
import java.util.List;
import java.util.Map;
import java.util.Set;

/**
 * The quests each boss needs (bossquests.txt) and what each of those quests needs first
 * (questlines.txt).
 */
public class BossQuests
{
	private final Map<String, List<Req>> byBoss;
	private final Map<String, List<String>> lines;

	private BossQuests(Map<String, List<Req>> byBoss, Map<String, List<String>> lines)
	{
		this.byBoss = byBoss;
		this.lines = lines;
	}

	public static BossQuests empty()
	{
		return new BossQuests(Collections.emptyMap(), Collections.emptyMap());
	}

	/** Quests needed to fight a boss. Empty when it needs none. */
	public List<Req> forBoss(String boss)
	{
		return byBoss.getOrDefault(boss, Collections.emptyList());
	}

	/** Everything to do before a quest, in order. Doesn't include the quest itself. */
	public List<String> lineFor(String quest)
	{
		return lines.getOrDefault(quest, Collections.emptyList());
	}

	public Set<String> getBosses()
	{
		return byBoss.keySet();
	}

	/** Every quest named anywhere, so the plugin knows which ones to check your progress on. */
	public Set<String> allQuests()
	{
		Set<String> out = new LinkedHashSet<>();
		for (List<Req> reqs : byBoss.values())
		{
			for (Req r : reqs)
			{
				out.add(r.getQuest());
			}
		}
		for (Map.Entry<String, List<String>> e : lines.entrySet())
		{
			out.add(e.getKey());
			out.addAll(e.getValue());
		}
		return out;
	}

	/** OSRS Wiki page for a quest. */
	public static String wikiUrl(String quest)
	{
		StringBuilder sb = new StringBuilder("https://oldschool.runescape.wiki/w/");
		for (char c : quest.toCharArray())
		{
			if (c == ' ')
			{
				sb.append('_');
			}
			else if (Character.isLetterOrDigit(c) || c == '-' || c == '_' || c == '.' || c == '(' || c == ')')
			{
				sb.append(c);
			}
			else
			{
				sb.append('%').append(String.format("%02X", (int) c));
			}
		}
		return sb.toString();
	}

	/** One quest a boss needs. */
	public static class Req
	{
		private final String quest;
		private final String note;

		Req(String quest, String note)
		{
			this.quest = quest;
			this.note = note;
		}

		public String getQuest()
		{
			return quest;
		}

		/** Extra detail, e.g. that the quest only has to be started. Empty if none. */
		public String getNote()
		{
			return note;
		}
	}

	/** Parse bossquests.txt (boss|quest|note) and questlines.txt (quest|needed first;needed first). */
	public static BossQuests load(InputStream bossFile, InputStream lineFile) throws IOException
	{
		Map<String, List<Req>> byBoss = new LinkedHashMap<>();
		for (String[] f : rows(bossFile))
		{
			if (f.length >= 2 && !f[0].isEmpty() && !f[1].isEmpty())
			{
				byBoss.computeIfAbsent(f[0], k -> new ArrayList<>()).add(new Req(f[1], f.length > 2 ? f[2] : ""));
			}
		}
		Map<String, List<String>> lines = new LinkedHashMap<>();
		for (String[] f : rows(lineFile))
		{
			if (f.length < 2 || f[0].isEmpty())
			{
				continue;
			}
			List<String> first = new ArrayList<>();
			for (String q : f[1].split(";"))
			{
				if (!q.trim().isEmpty() && !first.contains(q.trim()))
				{
					first.add(q.trim());
				}
			}
			lines.put(f[0], Collections.unmodifiableList(first));
		}
		for (Map.Entry<String, List<Req>> e : byBoss.entrySet())
		{
			e.setValue(Collections.unmodifiableList(e.getValue()));
		}
		return new BossQuests(byBoss, lines);
	}

	private static List<String[]> rows(InputStream in) throws IOException
	{
		List<String[]> out = new ArrayList<>();
		try (BufferedReader r = new BufferedReader(new InputStreamReader(in, StandardCharsets.UTF_8)))
		{
			String line;
			while ((line = r.readLine()) != null)
			{
				line = line.trim();
				if (line.isEmpty() || line.startsWith("#"))
				{
					continue;
				}
				String[] f = line.split("\\|", -1);
				for (int i = 0; i < f.length; i++)
				{
					f[i] = f[i].trim();
				}
				out.add(f);
			}
		}
		return out;
	}
}

package com.moneymaker.data;

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStream;
import java.io.InputStreamReader;
import java.nio.charset.StandardCharsets;
import java.util.ArrayList;
import java.util.Arrays;
import java.util.Collections;
import java.util.List;

/**
 * A gear setup for one boss, from the OSRS Wiki strategy page. Each slot holds tiers
 * ordered best to worst; each tier can have several equally-good alternatives.
 */
public class BossSetup
{
	private final String boss;
	private final String setup;
	private final String url;
	private final List<Slot> slots;

	public BossSetup(String boss, String setup, String url, List<Slot> slots)
	{
		this.boss = boss;
		this.setup = setup;
		this.url = url;
		this.slots = slots;
	}

	public String getBoss()
	{
		return boss;
	}

	public String getSetup()
	{
		return setup;
	}

	public String getUrl()
	{
		return url;
	}

	public List<Slot> getSlots()
	{
		return slots;
	}

	@Override
	public String toString()
	{
		return boss + " - " + setup;
	}

	public static class Slot
	{
		private final String name;
		/** Best first. */
		private final List<List<String>> tiers;

		public Slot(String name, List<List<String>> tiers)
		{
			this.name = name;
			this.tiers = tiers;
		}

		public String getName()
		{
			return name;
		}

		public List<List<String>> getTiers()
		{
			return tiers;
		}
	}

	/** Parse bosses.txt (BOSS| and SLOT| lines). */
	public static List<BossSetup> load(InputStream in) throws IOException
	{
		List<BossSetup> out = new ArrayList<>();
		String boss = null;
		String setup = null;
		String url = null;
		List<Slot> slots = null;
		try (BufferedReader r = new BufferedReader(new InputStreamReader(in, StandardCharsets.UTF_8)))
		{
			String line;
			while ((line = r.readLine()) != null)
			{
				String[] f = line.trim().split("\\|", -1);
				if (f[0].equals("BOSS") && f.length >= 4)
				{
					if (boss != null)
					{
						out.add(new BossSetup(boss, setup, url, Collections.unmodifiableList(slots)));
					}
					boss = f[1];
					setup = f[2];
					url = f[3];
					slots = new ArrayList<>();
				}
				else if (f[0].equals("SLOT") && f.length >= 3 && slots != null)
				{
					List<List<String>> tiers = new ArrayList<>();
					for (String group : f[2].split(";"))
					{
						List<String> alts = new ArrayList<>();
						for (String item : Arrays.asList(group.split(" / ")))
						{
							if (!item.trim().isEmpty())
							{
								alts.add(item.trim());
							}
						}
						tiers.add(Collections.unmodifiableList(alts));
					}
					slots.add(new Slot(f[1], Collections.unmodifiableList(tiers)));
				}
			}
		}
		if (boss != null)
		{
			out.add(new BossSetup(boss, setup, url, Collections.unmodifiableList(slots)));
		}
		return Collections.unmodifiableList(out);
	}
}

package com.moneymaker.data;

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStream;
import java.io.InputStreamReader;
import java.nio.charset.StandardCharsets;
import java.util.ArrayList;
import java.util.Collections;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;

/** Where to go on each farm run, in order, loaded from farmroutes.txt. */
public class FarmRoute
{
	/** Route key (a run's name or its group, lower case) to its stops in visiting order. */
	private final Map<String, List<Stop>> byKey;

	private FarmRoute(Map<String, List<Stop>> byKey)
	{
		this.byKey = byKey;
	}

	public static FarmRoute empty()
	{
		return new FarmRoute(Collections.emptyMap());
	}

	/** The stops for a run: a route written for that run by name wins, otherwise its group's route. */
	public List<Stop> stopsFor(FarmRun run)
	{
		List<Stop> stops = byKey.get(key(run.getName()));
		if (stops == null)
		{
			stops = byKey.get(key(run.getGroup()));
		}
		return stops == null ? Collections.emptyList() : stops;
	}

	private static String key(String s)
	{
		return s.trim().toLowerCase(java.util.Locale.ROOT);
	}

	/** One place to visit. */
	public static class Stop
	{
		private final String name;
		private final String travel;
		private final String needs;

		Stop(String name, String travel, String needs)
		{
			this.name = name;
			this.travel = travel;
			this.needs = needs;
		}

		public String getName()
		{
			return name;
		}

		/** How to get there. May be empty. */
		public String getTravel()
		{
			return travel;
		}

		/** A level, quest or other thing you need for this stop. Empty if nothing. */
		public String getNeeds()
		{
			return needs;
		}
	}

	/** Parse farmroutes.txt: route|stop|how to get there|what you need */
	public static FarmRoute load(InputStream in) throws IOException
	{
		Map<String, List<Stop>> map = new LinkedHashMap<>();
		try (BufferedReader r = new BufferedReader(new InputStreamReader(in, StandardCharsets.UTF_8)))
		{
			String line;
			while ((line = r.readLine()) != null)
			{
				line = line.trim();
				if (line.isEmpty() || line.startsWith("#"))
				{
					continue;
				}
				String[] f = line.split("\\|", -1);
				if (f.length < 2 || f[0].trim().isEmpty() || f[1].trim().isEmpty())
				{
					continue;
				}
				map.computeIfAbsent(key(f[0]), k -> new ArrayList<>())
					.add(new Stop(f[1].trim(), f.length > 2 ? f[2].trim() : "", f.length > 3 ? f[3].trim() : ""));
			}
		}
		for (Map.Entry<String, List<Stop>> e : map.entrySet())
		{
			e.setValue(Collections.unmodifiableList(e.getValue()));
		}
		return new FarmRoute(map);
	}
}

package com.moneymaker.data;

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStream;
import java.io.InputStreamReader;
import java.nio.charset.StandardCharsets;
import java.util.ArrayList;
import java.util.Collections;
import java.util.List;
import java.util.Locale;

/** A farm run (or bird house run, or daily) with a growth timer, loaded from farmruns.txt. All amounts are per run. */
public class FarmRun
{
	private final String id;
	private final String group;
	private final String name;
	private final String skill;
	private final int level;
	private final boolean members;
	private final double growMinutes;
	private final double runMinutes;
	private final int patches;
	private final List<Recipe.Stack> inputs;
	private final List<Recipe.Stack> outputs;
	private final double coins;
	private final double xp;
	private final String note;
	private final String url;

	FarmRun(String group, String name, String skill, int level, boolean members, double growMinutes, double runMinutes,
		int patches, List<Recipe.Stack> inputs, List<Recipe.Stack> outputs, double coins, double xp, String note, String url)
	{
		this.id = name.toLowerCase(Locale.ROOT).replaceAll("[^a-z0-9]+", "_");
		this.group = group;
		this.name = name;
		this.skill = skill;
		this.level = level;
		this.members = members;
		this.growMinutes = growMinutes;
		this.runMinutes = runMinutes;
		this.patches = patches;
		this.inputs = inputs;
		this.outputs = outputs;
		this.coins = coins;
		this.xp = xp;
		this.note = note;
		this.url = url;
	}

	public String getId()
	{
		return id;
	}

	public String getGroup()
	{
		return group;
	}

	public String getName()
	{
		return name;
	}

	public String getSkill()
	{
		return skill;
	}

	public boolean hasSkill()
	{
		return !"NONE".equals(skill);
	}

	public int getLevel()
	{
		return level;
	}

	public boolean isMembers()
	{
		return members;
	}

	public double getGrowMinutes()
	{
		return growMinutes;
	}

	public double getRunMinutes()
	{
		return runMinutes;
	}

	public int getPatches()
	{
		return patches;
	}

	public List<Recipe.Stack> getInputs()
	{
		return inputs;
	}

	public List<Recipe.Stack> getOutputs()
	{
		return outputs;
	}

	/** Coins paid per run (fees); negative means coins or untradeable loot received. */
	public double getCoins()
	{
		return coins;
	}

	public double getXp()
	{
		return xp;
	}

	public String getNote()
	{
		return note;
	}

	public String getUrl()
	{
		return url;
	}

	/** A run priced at current GE prices. */
	public static class Priced
	{
		private final FarmRun run;
		private final long cost;
		private final long revenue;
		private final List<JobResult.Line> buy;
		private final List<JobResult.Line> sell;

		Priced(FarmRun run, long cost, long revenue, List<JobResult.Line> buy, List<JobResult.Line> sell)
		{
			this.run = run;
			this.cost = cost;
			this.revenue = revenue;
			this.buy = buy;
			this.sell = sell;
		}

		public FarmRun getRun()
		{
			return run;
		}

		/** Cash you need for one run (supplies and fees). */
		public long getCost()
		{
			return cost;
		}

		public long getProfit()
		{
			return revenue - cost;
		}

		/** Profit per real hour, if you do the run every time it's ready. */
		public long getProfitPerHour()
		{
			return Math.round(getProfit() * 60.0 / Math.max(run.growMinutes, run.runMinutes));
		}

		/** Profit per minute spent doing the run. */
		public long getProfitPerMinute()
		{
			return Math.round(getProfit() / Math.max(0.5, run.runMinutes));
		}

		public List<JobResult.Line> getBuy()
		{
			return buy;
		}

		public List<JobResult.Line> getSell()
		{
			return sell;
		}
	}

	/** Price this run, or null if an item has no price. */
	public Priced price(PriceBook prices, PriceMode mode)
	{
		// coins: positive is a fee you pay, negative is coins or untradeable loot you get
		double cost = Math.max(0, coins);
		List<JobResult.Line> buy = new ArrayList<>();
		for (Recipe.Stack s : inputs)
		{
			ItemPrice p = prices.get(s.getItem());
			if (p == null || p.buyPrice(mode) <= 0)
			{
				return null;
			}
			cost += p.buyPrice(mode) * s.getQty();
			buy.add(new JobResult.Line(p.getName(), s.getQty(), p.buyPrice(mode), p.getId()));
		}
		double revenue = Math.max(0, -coins);
		List<JobResult.Line> sell = new ArrayList<>();
		for (Recipe.Stack s : outputs)
		{
			ItemPrice p = prices.get(s.getItem());
			if (p == null || p.sellPrice(mode) <= 0)
			{
				return null;
			}
			long each = p.sellPrice(mode);
			revenue += (each - GeTax.perItem(p.getId(), p.getName(), each)) * s.getQty();
			sell.add(new JobResult.Line(p.getName(), s.getQty(), each, p.getId()));
		}
		return new Priced(this, Math.round(cost), Math.round(revenue), buy, sell);
	}

	/** Parse farmruns.txt: group|name|skill|level|members|grow|run|patches|inputs|outputs|coins|xp|note|url */
	public static List<FarmRun> load(InputStream in) throws IOException
	{
		List<FarmRun> list = new ArrayList<>();
		try (BufferedReader r = new BufferedReader(new InputStreamReader(in, StandardCharsets.UTF_8)))
		{
			String line;
			while ((line = r.readLine()) != null)
			{
				line = line.trim();
				if (line.isEmpty() || line.startsWith("#"))
				{
					continue;
				}
				String[] f = line.split("\\|", -1);
				if (f.length < 14)
				{
					continue;
				}
				try
				{
					list.add(new FarmRun(f[0], f[1], f[2], Integer.parseInt(f[3]), "1".equals(f[4]),
						Double.parseDouble(f[5]), Double.parseDouble(f[6]), Integer.parseInt(f[7]),
						Recipe.stacks(f[8]), Recipe.stacks(f[9]), Double.parseDouble(f[10]), Double.parseDouble(f[11]), f[12], f[13]));
				}
				catch (RuntimeException e)
				{
					org.slf4j.LoggerFactory.getLogger(FarmRun.class).warn("Skipping a farmruns.txt line that couldn't be read: {}", line, e);
				}
			}
		}
		return Collections.unmodifiableList(list);
	}
}

package com.moneymaker.data;

import java.util.Arrays;
import java.util.Collections;
import java.util.HashSet;
import java.util.Locale;
import java.util.Set;

/**
 * Grand Exchange sales tax: 2% of the sell price per item, rounded down,
 * capped at 5m per item. Items selling for under 50gp are exempt, as are bonds
 * and a short list of everyday items.
 */
public final class GeTax
{
	public static final int BOND_ID = 13190;
	private static final long CAP = 5_000_000L;

	/**
	 * Items the GE never taxes, by lower-case name. From the OSRS Wiki's Grand Exchange tax
	 * page (checked November 2026); update this if Jagex changes the list.
	 */
	private static final Set<String> EXEMPT = Collections.unmodifiableSet(new HashSet<>(Arrays.asList(
		"old school bond",
		"energy potion(1)", "energy potion(2)", "energy potion(3)", "energy potion(4)",
		"bronze arrow", "iron arrow", "steel arrow", "bronze dart", "iron dart", "steel dart", "mind rune",
		"bass", "bread", "cake", "cooked chicken", "cooked meat", "herring", "lobster", "mackerel", "meat pie",
		"pike", "salmon", "shrimps", "tuna",
		"ardougne teleport (tablet)", "camelot teleport (tablet)", "civitas illa fortis teleport (tablet)",
		"falador teleport (tablet)", "kourend castle teleport (tablet)", "lumbridge teleport (tablet)",
		"varrock teleport (tablet)", "teleport to house (tablet)",
		"games necklace(8)", "ring of dueling(8)",
		"chisel", "gardening trowel", "glassblowing pipe", "hammer", "needle", "pestle and mortar", "rake", "saw",
		"secateurs", "seed dibber", "shears", "spade", "watering can")));

	private GeTax()
	{
	}

	public static boolean isExempt(int itemId, String name)
	{
		return itemId == BOND_ID || (name != null && EXEMPT.contains(name.trim().toLowerCase(Locale.ROOT)));
	}

	/** Tax on one item, taking the exempt list into account. */
	public static long perItem(int itemId, String name, long price)
	{
		return isExempt(itemId, name) ? 0 : perItem(itemId, price);
	}

	public static long perItem(int itemId, long price)
	{
		if (itemId == BOND_ID || price < 50)
		{
			return 0;
		}
		return Math.min(price * 2 / 100, CAP);
	}

	/** Profit per item when buying at {@code buy} and selling at {@code sell}. */
	public static long margin(int itemId, long buy, long sell)
	{
		return sell - perItem(itemId, sell) - buy;
	}
}

package com.moneymaker.data;

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStream;
import java.io.InputStreamReader;
import java.nio.charset.StandardCharsets;
import java.util.ArrayList;
import java.util.Arrays;
import java.util.Collections;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Locale;
import java.util.Map;

/** Skilling tools, outfits and useful items per skill (gear.txt), checked against what you own. */
public class Gear
{
	/** An item you own: total quantity and where it is ("worn", "bag", "bank"). */
	public static class Owned
	{
		private final String name;
		private final long qty;
		private final String where;

		public Owned(String name, long qty, String where)
		{
			this.name = name;
			this.qty = qty;
			this.where = where;
		}

		public String getName()
		{
			return name;
		}

		public long getQty()
		{
			return qty;
		}

		public String getWhere()
		{
			return where;
		}
	}

	/** One line of the gear check. */
	public static class Line
	{
		public enum Kind
		{
			GOOD, UPGRADE, MISSING, INFO
		}

		private final Kind kind;
		private final String text;

		Line(Kind kind, String text)
		{
			this.kind = kind;
			this.text = text;
		}

		public Kind getKind()
		{
			return kind;
		}

		public String getText()
		{
			return text;
		}
	}

	private static class Tier
	{
		final int level;
		final String item;
		/** Same strength as the tier before it (e.g. gilded, 3rd age, infernal): counts if owned, never suggested. */
		final boolean equivalent;

		Tier(int level, String item)
		{
			this.level = level;
			this.equivalent = item.startsWith("=");
			this.item = equivalent ? item.substring(1) : item;
		}
	}

	private static class SkillGear
	{
		final Map<String, List<Tier>> tools = new LinkedHashMap<>();
		final List<String[]> outfits = new ArrayList<>();
		final List<String[]> useful = new ArrayList<>();
	}

	private final Map<String, SkillGear> bySkill;

	private Gear(Map<String, SkillGear> bySkill)
	{
		this.bySkill = bySkill;
	}

	public static Gear empty()
	{
		return new Gear(Collections.emptyMap());
	}

	/** Find an owned item by name; variants like "Dragon pickaxe (or)" count. */
	public static Owned find(Map<String, Owned> owned, String item)
	{
		String key = item.toLowerCase(Locale.ROOT);
		Owned exact = owned.get(key);
		if (exact != null)
		{
			return exact;
		}
		for (Map.Entry<String, Owned> e : owned.entrySet())
		{
			if (e.getKey().startsWith(key + " (") || e.getKey().startsWith(key + "("))
			{
				return e.getValue();
			}
		}
		return null;
	}

	/** What you have for a skill, the next upgrade you can use, and what's missing. */
	public List<Line> check(String skill, int level, Map<String, Owned> owned)
	{
		List<Line> out = new ArrayList<>();
		SkillGear g = bySkill.get(skill);
		if (g == null)
		{
			return out;
		}
		for (Map.Entry<String, List<Tier>> e : g.tools.entrySet())
		{
			Tier bestOwned = null;
			Owned bestOwnedItem = null;
			for (Tier t : e.getValue())
			{
				Owned o = find(owned, t.item);
				if (o != null && t.level <= level)
				{
					bestOwned = t;
					bestOwnedItem = o;
				}
			}
			Tier canUse = null;
			Tier next = null;
			for (Tier t : e.getValue())
			{
				int ownedLevel = bestOwned == null ? -1 : e.getValue().indexOf(bestOwned);
				if (e.getValue().indexOf(t) <= ownedLevel || t.equivalent)
				{
					continue;
				}
				if (t.level <= level)
				{
					canUse = t;
				}
				else if (next == null)
				{
					next = t;
				}
			}
			String group = e.getKey();
			if (bestOwned != null)
			{
				out.add(new Line(Line.Kind.GOOD, group + ": " + bestOwnedItem.getName() + " (" + bestOwnedItem.getWhere() + ")"));
			}
			else
			{
				out.add(new Line(Line.Kind.MISSING, group + ": none found"));
			}
			if (canUse != null)
			{
				out.add(new Line(Line.Kind.UPGRADE, "Upgrade you can use now: " + canUse.item + " (" + canUse.level + ")"));
			}
			else if (next != null)
			{
				out.add(new Line(Line.Kind.INFO, "Next: " + next.item + " at " + next.level));
			}
		}
		for (String[] o : g.outfits)
		{
			List<String> pieces = Arrays.asList(o[1].split(";"));
			List<String> missing = new ArrayList<>();
			for (String p : pieces)
			{
				if (find(owned, p) == null)
				{
					missing.add(p);
				}
			}
			int have = pieces.size() - missing.size();
			if (missing.isEmpty())
			{
				out.add(new Line(Line.Kind.GOOD, o[0] + ": full set (" + o[2] + ")"));
			}
			else
			{
				out.add(new Line(have > 0 ? Line.Kind.UPGRADE : Line.Kind.MISSING, o[0] + ": " + have + "/" + pieces.size()
					+ " (" + o[2] + ")" + (have > 0 ? " · missing " + shortList(missing) : "")));
			}
		}
		for (String[] u : g.useful)
		{
			Owned o = find(owned, u[0]);
			out.add(o != null
				? new Line(Line.Kind.GOOD, u[0] + (o.getQty() > 1 ? " ×" + String.format(Locale.ROOT, "%,d", o.getQty()) : "") + " (" + o.getWhere() + ")")
				: new Line(Line.Kind.MISSING, u[0] + ": not found · " + u[1]));
		}
		return out;
	}

	private static String shortList(List<String> items)
	{
		List<String> s = new ArrayList<>();
		for (String i : items)
		{
			String[] w = i.split(" ");
			s.add(w[w.length - 1]);
		}
		return String.join(", ", s);
	}

	/** Parse gear.txt. */
	public static Gear load(InputStream in) throws IOException
	{
		Map<String, SkillGear> map = new LinkedHashMap<>();
		try (BufferedReader r = new BufferedReader(new InputStreamReader(in, StandardCharsets.UTF_8)))
		{
			String line;
			while ((line = r.readLine()) != null)
			{
				String[] f = line.split("\\|", -1);
				if (f.length < 4)
				{
					continue;
				}
				SkillGear g = map.computeIfAbsent(f[1], k -> new SkillGear());
				if ("T".equals(f[0]) && f.length >= 5)
				{
					int level;
					try
					{
						level = Integer.parseInt(f[3]);
					}
					catch (NumberFormatException e)
					{
						org.slf4j.LoggerFactory.getLogger(Gear.class).warn("Skipping a gear.txt line that couldn't be read: {}", line);
						continue;
					}
					g.tools.computeIfAbsent(f[2], k -> new ArrayList<>()).add(new Tier(level, f[4]));
				}
				else if ("O".equals(f[0]) && f.length >= 5)
				{
					g.outfits.add(new String[]{f[2], f[3], f[4]});
				}
				else if ("U".equals(f[0]))
				{
					g.useful.add(new String[]{f[2], f[3]});
				}
			}
		}
		return new Gear(map);
	}
}

package com.moneymaker.data;

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStream;
import java.io.InputStreamReader;
import java.nio.charset.StandardCharsets;
import java.util.ArrayList;
import java.util.Collections;
import java.util.HashMap;
import java.util.List;
import java.util.Map;

/**
 * Prices gear. Most items trade on the GE under their own name; the rest are listed in
 * aliases.txt, either as tradeable parts (e.g. a charged weapon's uncharged version) or
 * as untradeable with a note on how to get them.
 */
public class GearPricer
{
	private final Map<String, Alias> aliases;

	public GearPricer(Map<String, Alias> aliases)
	{
		this.aliases = aliases;
	}

	/** Price of one gear option. */
	public static class Price
	{
		private final String name;
		/** 0 when untradeable or no price. */
		private final long cost;
		/** Item to show an icon for, -1 if none. */
		private final int iconId;
		private final String note;
		private final boolean tradeable;

		Price(String name, long cost, int iconId, String note, boolean tradeable)
		{
			this.name = name;
			this.cost = cost;
			this.iconId = iconId;
			this.note = note;
			this.tradeable = tradeable;
		}

		public String getName()
		{
			return name;
		}

		public long getCost()
		{
			return cost;
		}

		public int getIconId()
		{
			return iconId;
		}

		public String getNote()
		{
			return note;
		}

		public boolean isTradeable()
		{
			return tradeable;
		}
	}

	public Price price(String name, PriceBook prices)
	{
		if (name.contains(" + "))
		{
			return combo(name, prices);
		}

		Alias alias = aliases.get(PriceBook.key(name));
		if (alias == null)
		{
			ItemPrice p = prices.get(name);
			if (p != null && p.typical() > 0)
			{
				return new Price(name, p.typical(), p.getId(), null, true);
			}
			return new Price(name, 0, p != null ? p.getId() : -1, p != null ? "No recent price" : "Untradeable", false);
		}

		if (alias.parts.isEmpty())
		{
			return new Price(name, 0, -1, alias.note, false);
		}

		if (alias.anyOf)
		{
			// cheapest of several equivalent items
			Price best = null;
			for (Recipe.Stack s : alias.parts)
			{
				ItemPrice p = prices.get(s.getItem());
				if (p != null && p.typical() > 0 && (best == null || p.typical() < best.getCost()))
				{
					best = new Price(name, p.typical(), p.getId(), alias.note + " (cheapest: " + p.getName() + ")", true);
				}
			}
			return best != null ? best : new Price(name, 0, -1, alias.note, false);
		}

		long total = 0;
		int icon = -1;
		for (Recipe.Stack s : alias.parts)
		{
			ItemPrice p = prices.get(s.getItem());
			if (p == null || p.typical() <= 0)
			{
				return new Price(name, 0, -1, alias.note, false);
			}
			total += Math.round(p.typical() * s.getQty());
			if (icon < 0)
			{
				icon = p.getId();
			}
		}
		return new Price(name, total, icon, alias.note, true);
	}

	/** Several items used together (e.g. weapon switches): price the tradeable ones, list the rest. */
	private Price combo(String name, PriceBook prices)
	{
		long total = 0;
		int icon = -1;
		List<String> unpriced = new ArrayList<>();
		for (String part : name.split(" \\+ "))
		{
			Price p = price(part.trim(), prices);
			if (p.isTradeable())
			{
				total += p.getCost();
				if (icon < 0)
				{
					icon = p.getIconId();
				}
			}
			else
			{
				unpriced.add(part.trim());
			}
		}
		String note = "Used together (switches)" + (unpriced.isEmpty() ? "" : "; not priced: " + String.join(", ", unpriced));
		return new Price(name, total, icon, note, total > 0);
	}

	/** Cheapest priced option in a tier, or an untradeable option if none are priced. */
	public Price cheapestOf(List<String> options, PriceBook prices)
	{
		Price best = null;
		Price fallback = null;
		for (String o : options)
		{
			Price p = price(o, prices);
			if (p.isTradeable())
			{
				if (best == null || p.getCost() < best.getCost())
				{
					best = p;
				}
			}
			else if (fallback == null)
			{
				fallback = p;
			}
		}
		return best != null ? best : fallback;
	}

	static class Alias
	{
		final List<Recipe.Stack> parts;
		final boolean anyOf;
		final String note;

		Alias(List<Recipe.Stack> parts, boolean anyOf, String note)
		{
			this.parts = parts;
			this.anyOf = anyOf;
			this.note = note;
		}
	}

	/** Parse aliases.txt: name|parts|note. Parts are "A*1 + B*2" (all needed) or "A, B, C" (any one). */
	public static GearPricer load(InputStream in) throws IOException
	{
		Map<String, Alias> map = new HashMap<>();
		try (BufferedReader r = new BufferedReader(new InputStreamReader(in, StandardCharsets.UTF_8)))
		{
			String line;
			while ((line = r.readLine()) != null)
			{
				line = line.trim();
				if (line.isEmpty() || line.startsWith("#"))
				{
					continue;
				}
				String[] f = line.split("\\|", -1);
				if (f.length < 3)
				{
					continue;
				}
				String partsText = f[1].trim();
				boolean anyOf = partsText.contains(",");
				List<Recipe.Stack> parts = new ArrayList<>();
				if (!partsText.isEmpty())
				{
					for (String p : partsText.split(anyOf ? "," : "\\+"))
					{
						p = p.trim();
						int star = p.lastIndexOf('*');
						if (star > 0)
						{
							int qty;
							try
							{
								qty = Integer.parseInt(p.substring(star + 1).trim());
							}
							catch (NumberFormatException e)
							{
								// not a quantity after all (a name with a * in it): treat it as one item
								parts.add(new Recipe.Stack(p, 1));
								continue;
							}
							parts.add(new Recipe.Stack(p.substring(0, star).trim(), qty));
						}
						else
						{
							parts.add(new Recipe.Stack(p, 1));
						}
					}
				}
				map.put(PriceBook.key(f[0]), new Alias(Collections.unmodifiableList(parts), anyOf, f[2].trim()));
			}
		}
		return new GearPricer(map);
	}
}

package com.moneymaker.data;

import java.util.ArrayList;
import java.util.Collections;
import java.util.List;
import java.util.Map;

/** Working out how to pay for a goal: what you have, what you still need and the quickest jobs to earn it. */
public final class GoalPlan
{
	private static final long PLATINUM_TOKEN_VALUE = 1000;

	private GoalPlan()
	{
	}

	/** Coins you hold (bag and bank), counting platinum tokens at 1,000 each. */
	public static long coins(Map<String, Gear.Owned> have)
	{
		long total = 0;
		Gear.Owned coins = have.get("coins");
		if (coins != null)
		{
			total += coins.getQty();
		}
		Gear.Owned tokens = have.get("platinum token");
		if (tokens != null)
		{
			total += tokens.getQty() * PLATINUM_TOKEN_VALUE;
		}
		return total;
	}

	/** One job and how long it takes to earn the amount. */
	public static class Earner
	{
		private final JobResult job;
		private final double hours;

		Earner(JobResult job, double hours)
		{
			this.job = job;
			this.hours = hours;
		}

		public JobResult getJob()
		{
			return job;
		}

		public double getHours()
		{
			return hours;
		}
	}

	/**
	 * The quickest jobs for earning an amount: best gp/hr first. Leaves out jobs that lose money
	 * and ones whose prices can't be trusted (old prices, or products that won't sell fast enough).
	 */
	public static List<Earner> earners(List<JobResult> jobs, long gpNeeded, int max)
	{
		List<JobResult> good = new ArrayList<>();
		for (JobResult j : jobs)
		{
			if (j != null && j.getGpPerHour() > 0 && !j.isStale() && !j.isLowVolume())
			{
				good.add(j);
			}
		}
		good.sort((a, b) -> Long.compare(b.getGpPerHour(), a.getGpPerHour()));
		List<Earner> out = new ArrayList<>();
		for (JobResult j : good)
		{
			if (out.size() >= max)
			{
				break;
			}
			out.add(new Earner(j, Math.max(0, gpNeeded) / (double) j.getGpPerHour()));
		}
		return Collections.unmodifiableList(out);
	}

	/** What the supplies for a training route cost to buy. Items with no price are left out. */
	public static long suppliesCost(List<Training.Step> steps, PriceBook prices, PriceMode mode)
	{
		long cost = 0;
		for (Training.Step s : steps)
		{
			long actions = s.getActions();
			for (Recipe.Stack need : s.getMethod().getNeeds())
			{
				ItemPrice p = prices.get(need.getItem());
				if (p != null)
				{
					cost += (long) Math.ceil(need.getQty() * actions) * p.buyPrice(mode);
				}
			}
		}
		return cost;
	}

	/** Total hours of play in a training route. */
	public static double hours(List<Training.Step> steps)
	{
		double h = 0;
		for (Training.Step s : steps)
		{
			h += s.getHours();
		}
		return h;
	}
}

package com.moneymaker.data;

/** Live price info for one item, merged from the wiki's latest and 1h endpoints. */
public class ItemPrice
{
	private final int id;
	private final String name;
	private final int limit;
	/** Latest instant-buy price (someone paid this). */
	private final long high;
	/** Latest instant-sell price (someone sold for this). */
	private final long low;
	private final long avgHigh;
	private final long avgLow;
	private final long hourVolume;
	/** When it last traded (epoch seconds), 0 if unknown. */
	private final long lastTrade;

	public ItemPrice(int id, String name, int limit, long high, long low, long avgHigh, long avgLow, long hourVolume)
	{
		this(id, name, limit, high, low, avgHigh, avgLow, hourVolume, 0);
	}

	public ItemPrice(int id, String name, int limit, long high, long low, long avgHigh, long avgLow, long hourVolume,
		long lastTrade)
	{
		this.lastTrade = lastTrade;
		this.id = id;
		this.name = name;
		this.limit = limit;
		this.high = high;
		this.low = low;
		this.avgHigh = avgHigh;
		this.avgLow = avgLow;
		this.hourVolume = hourVolume;
	}

	public int getId()
	{
		return id;
	}

	public String getName()
	{
		return name;
	}

	/** GE buy limit per 4 hours, 0 if unknown. */
	public int getLimit()
	{
		return limit;
	}

	public long getHourVolume()
	{
		return hourVolume;
	}

	/** How long a price can go without a trade before we stop trusting it. */
	public static final long STALE_AFTER_MS = 24 * 60 * 60 * 1000L;

	/**
	 * True when nothing traded in the last hour and the last known trade is over a day old,
	 * so the price shown may be nowhere near what you'd really get.
	 */
	public boolean isStale(long nowMs)
	{
		return hourVolume <= 0 && lastTrade > 0 && nowMs - lastTrade * 1000 > STALE_AFTER_MS;
	}

	/** What you'd pay to buy one, for the chosen price mode. 0 if unknown. */
	public long buyPrice(PriceMode mode)
	{
		switch (mode)
		{
			case INSTANT:
				return first(high, avgHigh, low);
			case PATIENT:
				return first(low, avgLow, high);
			default:
				return mid(first(avgHigh, high), first(avgLow, low));
		}
	}

	/** What you'd get for selling one (before tax), for the chosen price mode. 0 if unknown. */
	public long sellPrice(PriceMode mode)
	{
		switch (mode)
		{
			case INSTANT:
				return first(low, avgLow, high);
			case PATIENT:
				return first(high, avgHigh, low);
			default:
				return mid(first(avgHigh, high), first(avgLow, low));
		}
	}

	/** A single "typical" price, used for gear costs. */
	public long typical()
	{
		return mid(first(avgHigh, high), first(avgLow, low));
	}

	private static long first(long... values)
	{
		for (long v : values)
		{
			if (v > 0)
			{
				return v;
			}
		}
		return 0;
	}

	private static long mid(long a, long b)
	{
		if (a <= 0)
		{
			return b;
		}
		if (b <= 0)
		{
			return a;
		}
		return (a + b) / 2;
	}
}

package com.moneymaker.data;

import java.util.ArrayList;
import java.util.Collections;
import java.util.List;

/** A recipe priced at current GE prices, plus what it takes to reach your next level. */
public class JobResult
{
	private final Recipe recipe;
	private final double costEach;
	private final double revenueEach;
	private final double actionsPerHour;
	private final boolean limitCapped;
	private final String cappedBy;
	private final boolean lowVolume;
	/** An item whose price is over a day old, or null. */
	private final String staleItem;
	private final List<Line> inputLines;
	private final List<Line> outputLines;
	/** Next-level info; null when there's no skill, no XP, or you're 99. */
	private final NextLevel next;

	private JobResult(Recipe recipe, double costEach, double revenueEach, double actionsPerHour, boolean limitCapped,
		String cappedBy, boolean lowVolume, String staleItem, List<Line> inputLines, List<Line> outputLines, NextLevel next)
	{
		this.staleItem = staleItem;
		this.recipe = recipe;
		this.costEach = costEach;
		this.revenueEach = revenueEach;
		this.actionsPerHour = actionsPerHour;
		this.limitCapped = limitCapped;
		this.cappedBy = cappedBy;
		this.lowVolume = lowVolume;
		this.inputLines = inputLines;
		this.outputLines = outputLines;
		this.next = next;
	}

	public Recipe getRecipe()
	{
		return recipe;
	}

	public long getCostEach()
	{
		return Math.round(costEach);
	}

	public long getRevenueEach()
	{
		return Math.round(revenueEach);
	}

	public long getProfitEach()
	{
		return Math.round(revenueEach - costEach);
	}

	public double getActionsPerHour()
	{
		return actionsPerHour;
	}

	public long getGpPerHour()
	{
		return Math.round((revenueEach - costEach) * actionsPerHour);
	}

	public boolean isLimitCapped()
	{
		return limitCapped;
	}

	public String getCappedBy()
	{
		return cappedBy;
	}

	public boolean isLowVolume()
	{
		return lowVolume;
	}

	/** True when one of the main items hasn't traded for over a day, so the gp/hr can't be trusted. */
	public boolean isStale()
	{
		return staleItem != null;
	}

	public String getStaleItem()
	{
		return staleItem;
	}

	public List<Line> getInputLines()
	{
		return inputLines;
	}

	public List<Line> getOutputLines()
	{
		return outputLines;
	}

	public NextLevel getNext()
	{
		return next;
	}

	/** One priced item line, e.g. "2 x Vial of water @ 4". */
	public static class Line
	{
		private final String item;
		private final double qty;
		private final long priceEach;
		private final int itemId;

		Line(String item, double qty, long priceEach, int itemId)
		{
			this.item = item;
			this.qty = qty;
			this.priceEach = priceEach;
			this.itemId = itemId;
		}

		public String getItem()
		{
			return item;
		}

		public double getQty()
		{
			return qty;
		}

		public long getPriceEach()
		{
			return priceEach;
		}

		public int getItemId()
		{
			return itemId;
		}
	}

	/** What reaching the next level with this job looks like. */
	public static class NextLevel
	{
		private final int currentLevel;
		private final int targetLevel;
		private final long xpNeeded;
		private final long actions;
		private final long profit;
		private final double hours;
		/** Shopping list: total qty of each input for all the actions. */
		private final List<Line> shopping;
		private final long shoppingCost;

		NextLevel(int currentLevel, int targetLevel, long xpNeeded, long actions, long profit, double hours,
			List<Line> shopping, long shoppingCost)
		{
			this.currentLevel = currentLevel;
			this.targetLevel = targetLevel;
			this.xpNeeded = xpNeeded;
			this.actions = actions;
			this.profit = profit;
			this.hours = hours;
			this.shopping = shopping;
			this.shoppingCost = shoppingCost;
		}

		public int getCurrentLevel()
		{
			return currentLevel;
		}

		public int getTargetLevel()
		{
			return targetLevel;
		}

		public long getXpNeeded()
		{
			return xpNeeded;
		}

		public long getActions()
		{
			return actions;
		}

		public long getProfit()
		{
			return profit;
		}

		public double getHours()
		{
			return hours;
		}

		public List<Line> getShopping()
		{
			return shopping;
		}

		public long getShoppingCost()
		{
			return shoppingCost;
		}
	}

	/**
	 * Price a recipe. Returns null if any item has no price.
	 *
	 * @param level current level in the recipe's skill (0 if unknown)
	 * @param xp current XP in the recipe's skill (-1 if unknown)
	 * @param xpForNextLevel XP needed for level+1 (from RuneLite's Experience table), or -1
	 */
	public static JobResult evaluate(Recipe r, PriceBook prices, PriceMode mode, int speedPercent,
		int level, long xp, long xpForNextLevel)
	{
		double cost = r.getCoinsPerAction();
		List<Line> ins = new ArrayList<>();
		double rate = r.getPerHour() * Math.max(1, speedPercent) / 100.0;
		boolean capped = false;
		String cappedBy = null;
		String staleItem = null;
		long now = prices.getUpdatedAt();

		for (Recipe.Stack s : r.getInputs())
		{
			ItemPrice p = prices.get(s.getItem());
			if (p == null || p.buyPrice(mode) <= 0)
			{
				return null;
			}
			long each = p.buyPrice(mode);
			cost += each * s.getQty();
			ins.add(new Line(p.getName(), s.getQty(), each, p.getId()));
			if (staleItem == null && p.isStale(now))
			{
				staleItem = p.getName();
			}

			// GE buy limit: you can only buy `limit` every 4 hours
			if (p.getLimit() > 0 && s.getQty() > 0)
			{
				double maxPerHour = p.getLimit() / s.getQty() / 4.0;
				if (maxPerHour < rate)
				{
					rate = maxPerHour;
					capped = true;
					cappedBy = p.getName();
				}
			}
		}

		double revenue = 0;
		boolean lowVolume = false;
		List<Line> outs = new ArrayList<>();
		for (Recipe.Stack s : r.getOutputs())
		{
			ItemPrice p = prices.get(s.getItem());
			if (p == null || p.sellPrice(mode) <= 0)
			{
				return null;
			}
			long each = p.sellPrice(mode);
			revenue += (each - GeTax.perItem(p.getId(), p.getName(), each)) * s.getQty();
			outs.add(new Line(p.getName(), s.getQty(), each, p.getId()));
			// like low volume, only the main products count, not rare drops
			if (staleItem == null && s.getQty() >= 0.2 && p.isStale(now))
			{
				staleItem = p.getName();
			}
			// only flag the main products, not rare drops
			if (s.getQty() >= 0.2 && p.getHourVolume() < rate * s.getQty())
			{
				lowVolume = true;
			}
		}
		// show the most valuable product first
		outs.sort((a, b) -> Double.compare(b.getPriceEach() * b.getQty(), a.getPriceEach() * a.getQty()));

		NextLevel next = null;
		if (r.hasSkill() && r.getXp() > 0 && xp >= 0 && xpForNextLevel > xp && level > 0 && level < 99)
		{
			long xpNeeded = xpForNextLevel - xp;
			long actions = (long) Math.ceil(xpNeeded / r.getXp());
			List<Line> shopping = new ArrayList<>();
			long shoppingCost = 0;
			for (Line l : ins)
			{
				double qty = Math.ceil(l.getQty() * actions);
				shopping.add(new Line(l.getItem(), qty, l.getPriceEach(), l.getItemId()));
				shoppingCost += Math.round(qty * l.getPriceEach());
			}
			shoppingCost += Math.round(Math.max(0, r.getCoinsPerAction()) * actions);
			long profit = Math.round((revenue - cost) * actions);
			double hours = rate > 0 ? actions / rate : 0;
			next = new NextLevel(level, level + 1, xpNeeded, actions, profit, hours,
				Collections.unmodifiableList(shopping), shoppingCost);
		}

		return new JobResult(r, cost, revenue, rate, capped, cappedBy, lowVolume, staleItem,
			Collections.unmodifiableList(ins), Collections.unmodifiableList(outs), next);
	}
}

package com.moneymaker.data;

import java.util.Collections;
import java.util.Locale;
import java.util.Map;

/** All current prices, looked up by item name (case-insensitive). */
public class PriceBook
{
	public static final PriceBook EMPTY = new PriceBook(Collections.emptyMap(), 0);

	private final Map<String, ItemPrice> byName;
	private final long updatedAt;

	public PriceBook(Map<String, ItemPrice> byName, long updatedAt)
	{
		this.byName = byName;
		this.updatedAt = updatedAt;
	}

	public static String key(String name)
	{
		return name.trim().toLowerCase(Locale.ROOT);
	}

	public ItemPrice get(String name)
	{
		return byName.get(key(name));
	}

	/**
	 * Items whose name contains the text, best matches first (exact, then starts-with, then shorter
	 * names). Only items with a price are returned.
	 */
	public java.util.List<ItemPrice> search(String text, int max)
	{
		String q = key(text);
		java.util.List<ItemPrice> out = new java.util.ArrayList<>();
		if (q.isEmpty())
		{
			return out;
		}
		for (Map.Entry<String, ItemPrice> e : byName.entrySet())
		{
			if (e.getKey().contains(q) && e.getValue().typical() > 0)
			{
				out.add(e.getValue());
			}
		}
		out.sort(java.util.Comparator
			.comparing((ItemPrice p) -> !key(p.getName()).equals(q))
			.thenComparing(p -> !key(p.getName()).startsWith(q))
			.thenComparing(p -> p.getName().length())
			.thenComparing(ItemPrice::getName));
		return out.size() > max ? new java.util.ArrayList<>(out.subList(0, max)) : out;
	}

	public boolean isEmpty()
	{
		return byName.isEmpty();
	}

	public int size()
	{
		return byName.size();
	}

	public long getUpdatedAt()
	{
		return updatedAt;
	}
}

