package com.moneymaker.data;

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStream;
import java.io.InputStreamReader;
import java.nio.charset.StandardCharsets;
import java.util.ArrayList;
import java.util.Collections;
import java.util.List;

/**
 * One money-making job, loaded from recipes.txt.
 * Quantities can be fractions, e.g. 0.05 of a rare drop per kill.
 */
public class Recipe
{
	private static final org.slf4j.Logger log = org.slf4j.LoggerFactory.getLogger(Recipe.class);

	private final String category;
	private final String name;
	/** RuneLite Skill enum name, or "NONE". This is the skill used for the next-level planner. */
	private final String skill;
	private final int level;
	private final boolean members;
	private final double perHour;
	/** Coins paid per action (fees). Negative means coins received, e.g. from pickpocketing. */
	private final double coinsPerAction;
	private final List<Stack> inputs;
	private final List<Stack> outputs;
	private final double xp;
	/** Every skill level needed, including the main one. */
	private final List<Req> reqs;
	/** What one action is, e.g. "kill", "fish", "min". */
	private final String unit;
	/** OSRS Wiki guide for this method, or empty. */
	private final String url;

	public Recipe(String category, String name, String skill, int level, boolean members, double perHour,
		double coinsPerAction, List<Stack> inputs, List<Stack> outputs, double xp, List<Req> reqs, String unit, String url)
	{
		this.category = category;
		this.name = name;
		this.skill = skill;
		this.level = level;
		this.members = members;
		this.perHour = perHour;
		this.coinsPerAction = coinsPerAction;
		this.inputs = inputs;
		this.outputs = outputs;
		this.xp = xp;
		this.reqs = reqs;
		this.unit = unit;
		this.url = url;
	}

	public String getCategory()
	{
		return category;
	}

	public String getName()
	{
		return name;
	}

	public String getSkill()
	{
		return skill;
	}

	public boolean hasSkill()
	{
		return !"NONE".equals(skill);
	}

	public int getLevel()
	{
		return level;
	}

	public boolean isMembers()
	{
		return members;
	}

	public double getPerHour()
	{
		return perHour;
	}

	public double getCoinsPerAction()
	{
		return coinsPerAction;
	}

	public List<Stack> getInputs()
	{
		return inputs;
	}

	public List<Stack> getOutputs()
	{
		return outputs;
	}

	public double getXp()
	{
		return xp;
	}

	public List<Req> getReqs()
	{
		return reqs;
	}

	public String getUnit()
	{
		return unit;
	}

	public String getUrl()
	{
		return url;
	}

	/** An item name and how many of it. */
	public static class Stack
	{
		private final String item;
		private final double qty;

		public Stack(String item, double qty)
		{
			this.item = item;
			this.qty = qty;
		}

		public String getItem()
		{
			return item;
		}

		public double getQty()
		{
			return qty;
		}
	}

	/** A skill level requirement. */
	public static class Req
	{
		private final String skill;
		private final int level;

		public Req(String skill, int level)
		{
			this.skill = skill;
			this.level = level;
		}

		public String getSkill()
		{
			return skill;
		}

		public int getLevel()
		{
			return level;
		}
	}

	/**
	 * Parse recipes.txt:
	 * category|name|skill|level|members|perHour|coins|inputs|outputs|xp[|reqs|unit|url]
	 * where reqs is "SKILL:level;SKILL:level".
	 */
	public static List<Recipe> load(InputStream in) throws IOException
	{
		List<Recipe> list = new ArrayList<>();
		try (BufferedReader r = new BufferedReader(new InputStreamReader(in, StandardCharsets.UTF_8)))
		{
			String line;
			while ((line = r.readLine()) != null)
			{
				line = line.trim();
				if (line.isEmpty() || line.startsWith("#"))
				{
					continue;
				}
				String[] f = line.split("\\|", -1);
				if (f.length < 10)
				{
					continue;
				}
				try
				{
					list.add(parse(f));
				}
				catch (RuntimeException e)
				{
					log.warn("Skipping a recipes.txt line that couldn't be read: {}", line, e);
				}
			}
		}
		return Collections.unmodifiableList(list);
	}

	private static Recipe parse(String[] f)
	{
		String skill = f[2];
		int level = Integer.parseInt(f[3]);
		List<Req> reqs = new ArrayList<>();
		if (!"NONE".equals(skill))
		{
			reqs.add(new Req(skill, level));
		}
		if (f.length > 10)
		{
			for (String part : f[10].split(";"))
			{
				int colon = part.indexOf(':');
				if (colon > 0)
				{
					String s = part.substring(0, colon);
					if (!s.equals(skill))
					{
						reqs.add(new Req(s, Integer.parseInt(part.substring(colon + 1))));
					}
				}
			}
		}
		return new Recipe(f[0], f[1], skill, level, "1".equals(f[4]),
			Double.parseDouble(f[5]), Double.parseDouble(f[6]), stacks(f[7]), stacks(f[8]), Double.parseDouble(f[9]),
			Collections.unmodifiableList(reqs), f.length > 11 ? f[11] : "", f.length > 12 ? f[12] : "");
	}

	static List<Stack> stacks(String s)
	{
		List<Stack> out = new ArrayList<>();
		for (String part : s.split(";"))
		{
			if (part.isEmpty())
			{
				continue;
			}
			int star = part.lastIndexOf('*');
			out.add(new Stack(part.substring(0, star), Double.parseDouble(part.substring(star + 1))));
		}
		return Collections.unmodifiableList(out);
	}
}

package com.moneymaker.data;

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStream;
import java.io.InputStreamReader;
import java.nio.charset.StandardCharsets;
import java.util.ArrayList;
import java.util.Collections;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;

/** XP training methods and milestone levels for every skill, loaded from training.txt, plus a route planner. */
public class Training
{
	private static final int[] XP = new int[100];

	static
	{
		// standard OSRS experience table
		double points = 0;
		for (int lvl = 1; lvl < 100; lvl++)
		{
			XP[lvl] = (int) Math.floor(points / 4);
			points += Math.floor(lvl + 300 * Math.pow(2, lvl / 7.0));
		}
	}

	/** XP needed to reach a level (1-99). */
	public static int xpForLevel(int level)
	{
		return XP[Math.max(1, Math.min(99, level))];
	}

	/** Level for an amount of XP. */
	public static int levelForXp(long xp)
	{
		int lvl = 1;
		while (lvl < 99 && XP[lvl + 1] <= xp)
		{
			lvl++;
		}
		return lvl;
	}

	private final Map<String, List<Method>> methods;
	private final Map<String, List<Milestone>> milestones;

	private Training(Map<String, List<Method>> methods, Map<String, List<Milestone>> milestones)
	{
		this.methods = methods;
		this.milestones = milestones;
	}

	public static Training empty()
	{
		return new Training(Collections.emptyMap(), Collections.emptyMap());
	}

	public List<String> getSkills()
	{
		return new ArrayList<>(methods.keySet());
	}

	public List<Method> getMethods(String skill)
	{
		return methods.getOrDefault(skill, Collections.emptyList());
	}

	public List<Milestone> getMilestones(String skill)
	{
		return milestones.getOrDefault(skill, Collections.emptyList());
	}

	/** A level that unlocks something worth aiming for. */
	public static class Milestone
	{
		private final int level;
		private final String text;

		Milestone(int level, String text)
		{
			this.level = level;
			this.text = text;
		}

		public int getLevel()
		{
			return level;
		}

		public String getText()
		{
			return text;
		}
	}

	/** One way to train a skill. */
	public static class Method
	{
		private final String skill;
		private final String name;
		private final int level;
		private final double xpAtMin;
		private final double xpAt99;
		private final double xpEach;
		private final String unit;
		private final boolean ironman;
		private final boolean members;
		private final boolean intense;
		private final int cycleMinutes;
		private final List<Recipe.Stack> needs;
		private final List<Recipe.Stack> gives;
		private final String requirements;
		private final String note;

		Method(String[] f)
		{
			skill = f[1];
			name = f[2];
			level = Integer.parseInt(f[3]);
			xpAtMin = Double.parseDouble(f[4]);
			xpAt99 = Double.parseDouble(f[5]);
			xpEach = Double.parseDouble(f[6]);
			unit = f[7];
			ironman = "1".equals(f[8]);
			members = "1".equals(f[9]);
			intense = "1".equals(f[10]);
			cycleMinutes = Integer.parseInt(f[11]);
			needs = Recipe.stacks(f[12]);
			gives = Recipe.stacks(f[13]);
			requirements = f[14];
			note = f[15];
		}

		public String getSkill()
		{
			return skill;
		}

		public String getName()
		{
			return name;
		}

		public int getLevel()
		{
			return level;
		}

		/** Typical xp per hour at a level (interpolated between the method's level and 99). */
		public double xpPerHour(int atLevel)
		{
			if (level >= 99)
			{
				return xpAt99;
			}
			double t = Math.max(0, Math.min(1, (atLevel - level) / (double) (99 - level)));
			return xpAtMin + (xpAt99 - xpAtMin) * t;
		}

		/** For ranking: xp per real hour (timed runs are limited by how often you can do them). */
		double effectiveRate(int atLevel)
		{
			return cycleMinutes > 0 && xpEach > 0 ? xpEach * 60.0 / cycleMinutes : xpPerHour(atLevel);
		}

		public double getXpEach()
		{
			return xpEach;
		}

		public String getUnit()
		{
			return unit.isEmpty() ? "action" : unit;
		}

		public boolean isIronman()
		{
			return ironman;
		}

		public boolean isMembers()
		{
			return members;
		}

		public boolean isIntense()
		{
			return intense;
		}

		/** For timed methods (farm runs): minutes between runs, else 0. */
		public int getCycleMinutes()
		{
			return cycleMinutes;
		}

		public List<Recipe.Stack> getNeeds()
		{
			return needs;
		}

		public List<Recipe.Stack> getGives()
		{
			return gives;
		}

		public String getRequirements()
		{
			return requirements;
		}

		public String getNote()
		{
			return note;
		}
	}

	/** Which methods the planner may use. */
	public static class Filter
	{
		public boolean ironman;
		public boolean members = true;
		public boolean intense = true;
		/** Only methods that don't use up supplies. */
		public boolean noSupplies;
		/** Only timed methods (farm runs); they're ranked by xp per real hour. */
		public boolean timedOnly;

		boolean allows(Method m)
		{
			return (!ironman || m.ironman) && (members || !m.members) && (intense || !m.intense)
				&& (!noSupplies || m.needs.isEmpty()) && (!timedOnly || m.cycleMinutes > 0);
		}
	}

	/** One stretch of the route: levels from-to with one method. */
	public static class Step
	{
		private final Method method;
		private final int fromLevel;
		private int toLevel;
		private double xp;
		private double hours;

		Step(Method method, int fromLevel)
		{
			this.method = method;
			this.fromLevel = fromLevel;
			this.toLevel = fromLevel;
		}

		public Method getMethod()
		{
			return method;
		}

		public int getFromLevel()
		{
			return fromLevel;
		}

		public int getToLevel()
		{
			return toLevel;
		}

		public double getXp()
		{
			return xp;
		}

		/** Hours of play. */
		public double getHours()
		{
			return hours;
		}

		/** Actions (kills, logs, casts, runs...), or 0 when the method has no per-action xp. */
		public long getActions()
		{
			return method.xpEach > 0 ? (long) Math.ceil(xp / method.xpEach) : 0;
		}

		/** For timed methods: real days if you do one run every cycle. */
		public double getDays()
		{
			return method.cycleMinutes > 0 ? getActions() * method.cycleMinutes / 1440.0 : 0;
		}
	}

	/**
	 * Fastest route from the current xp to a target level: at every level, use the best method you can.
	 * Returns an empty list if nothing is available.
	 */
	public List<Step> plan(String skill, long fromXp, int toLevel, Filter filter)
	{
		List<Step> steps = new ArrayList<>();
		long xp = fromXp;
		long target = xpForLevel(toLevel);
		Step current = null;
		while (xp < target)
		{
			int lvl = levelForXp(xp);
			long next = Math.min(target, xpForLevel(lvl + 1));
			Method best = best(skill, lvl, filter);
			if (best == null)
			{
				break;
			}
			double rate = best.xpPerHour(lvl);
			if (rate <= 0)
			{
				break;
			}
			if (current == null || current.method != best)
			{
				current = new Step(best, lvl);
				steps.add(current);
			}
			current.xp += next - xp;
			current.hours += (next - xp) / rate;
			current.toLevel = levelForXp(next);
			xp = next;
		}
		return steps;
	}

	/** The fastest method available at a level, or null. */
	public Method best(String skill, int level, Filter filter)
	{
		Method best = null;
		for (Method m : getMethods(skill))
		{
			if (m.level <= level && filter.allows(m) && (best == null || m.effectiveRate(level) > best.effectiveRate(level)))
			{
				best = m;
			}
		}
		return best;
	}

	/** Parse training.txt. */
	public static Training load(InputStream in) throws IOException
	{
		Map<String, List<Method>> methods = new LinkedHashMap<>();
		Map<String, List<Milestone>> milestones = new LinkedHashMap<>();
		try (BufferedReader r = new BufferedReader(new InputStreamReader(in, StandardCharsets.UTF_8)))
		{
			String line;
			while ((line = r.readLine()) != null)
			{
				String[] f = line.split("\\|", -1);
				try
				{
					if ("M".equals(f[0]) && f.length >= 4)
					{
						Milestone m = new Milestone(Integer.parseInt(f[2]), f[3]);
						milestones.computeIfAbsent(f[1], k -> new ArrayList<>()).add(m);
					}
					else if ("T".equals(f[0]) && f.length >= 16)
					{
						Method m = new Method(f);
						methods.computeIfAbsent(f[1], k -> new ArrayList<>()).add(m);
					}
				}
				catch (RuntimeException e)
				{
					org.slf4j.LoggerFactory.getLogger(Training.class).warn("Skipping a training.txt line that couldn't be read: {}", line, e);
				}
			}
		}
		milestones.values().forEach(l -> l.sort((a, b) -> Integer.compare(a.level, b.level)));
		return new Training(methods, milestones);
	}
}

package com.moneymaker.data;

import com.google.gson.Gson;
import com.google.gson.reflect.TypeToken;
import java.io.IOException;
import java.lang.reflect.Type;
import java.util.Collections;
import java.util.List;
import java.util.Map;
import javax.inject.Inject;
import javax.inject.Singleton;
import okhttp3.HttpUrl;
import okhttp3.OkHttpClient;
import okhttp3.Request;
import okhttp3.Response;
import okhttp3.ResponseBody;

/**
 * Client for the OSRS Wiki real-time prices API (https://prices.runescape.wiki).
 * The wiki asks for a descriptive User-Agent, so we send one.
 */
@Singleton
public class WikiPriceClient
{
	private static final HttpUrl BASE = HttpUrl.parse("https://prices.runescape.wiki/api/v1/osrs/");
	private static final String USER_AGENT = "RuneLite Adventurer's Ledger plugin - github.com/phattymatty10107-cmd/adventurers-ledger";

	private static final Type MAPPING_TYPE = new TypeToken<List<Mapping>>()
	{
	}.getType();

	private final OkHttpClient http;
	private final Gson gson;

	@Inject
	public WikiPriceClient(OkHttpClient http, Gson gson)
	{
		this.http = http;
		this.gson = gson;
	}

	public List<Mapping> fetchMapping() throws IOException
	{
		List<Mapping> list = get("mapping", MAPPING_TYPE);
		return list == null ? Collections.emptyList() : list;
	}

	public Map<Integer, Latest> fetchLatest() throws IOException
	{
		LatestResponse r = get("latest", LatestResponse.class);
		return r == null || r.data == null ? Collections.emptyMap() : r.data;
	}

	/** Average prices and volumes over the last hour. */
	public Map<Integer, Average> fetchHourly() throws IOException
	{
		return fetchAverage("1h");
	}

	/** Average prices and volumes over the last 24 hours. */
	public Map<Integer, Average> fetchDaily() throws IOException
	{
		return fetchAverage("24h");
	}

	private Map<Integer, Average> fetchAverage(String path) throws IOException
	{
		AverageResponse r = get(path, AverageResponse.class);
		return r == null || r.data == null ? Collections.emptyMap() : r.data;
	}

	private <T> T get(String path, Type type) throws IOException
	{
		Request request = new Request.Builder()
			.url(BASE.newBuilder().addPathSegment(path).build())
			.header("User-Agent", USER_AGENT)
			.build();

		try (Response response = http.newCall(request).execute())
		{
			ResponseBody body = response.body();
			if (!response.isSuccessful() || body == null)
			{
				throw new IOException("OSRS Wiki returned HTTP " + response.code() + " for /" + path);
			}
			return gson.fromJson(body.charStream(), type);
		}
	}

	public static class Mapping
	{
		public int id;
		public String name;
		public boolean members;
		public Integer limit;
	}

	public static class Latest
	{
		public Long high;
		public Long highTime;
		public Long low;
		public Long lowTime;
	}

	public static class Average
	{
		public Long avgHighPrice;
		public Long highPriceVolume;
		public Long avgLowPrice;
		public Long lowPriceVolume;
	}

	private static class LatestResponse
	{
		Map<Integer, Latest> data;
	}

	private static class AverageResponse
	{
		Map<Integer, Average> data;
	}
}

package com.moneymaker.ui;

import com.moneymaker.MoneyMakerPlugin;
import com.moneymaker.data.BossCheck;
import com.moneymaker.data.BossQuests;
import com.moneymaker.data.BossSetup;
import com.moneymaker.data.Gear;
import com.moneymaker.data.GearPricer;
import com.moneymaker.data.PriceBook;
import java.awt.BorderLayout;
import java.awt.Color;
import java.awt.Cursor;
import java.awt.GridLayout;
import java.awt.event.MouseAdapter;
import java.awt.event.MouseEvent;
import java.util.ArrayList;
import java.util.LinkedHashSet;
import java.util.List;
import java.util.Locale;
import java.util.Map;
import javax.swing.BoxLayout;
import javax.swing.JButton;
import javax.swing.JComboBox;
import javax.swing.JLabel;
import javax.swing.JPanel;
import javax.swing.border.EmptyBorder;
import net.runelite.api.QuestState;
import net.runelite.client.game.ItemManager;
import net.runelite.client.ui.ColorScheme;
import net.runelite.client.util.LinkBrowser;

/** Gear for each boss, per slot from starter to best in slot (OSRS Wiki ranking), at live GE prices. */
class BossesPanel extends JPanel
{
	private final MoneyMakerPlugin plugin;
	private final ItemManager itemManager;
	private final JComboBox<BossSetup> setups = new JComboBox<>();
	private final JLabel budget = stat();
	private final JLabel mid = stat();
	private final JLabel best = stat();
	private final JLabel untradeables = UiUtil.label(" ", UiUtil.MUTED, false);
	private final JPanel list = UiUtil.verticalList();

	BossesPanel(MoneyMakerPlugin plugin, ItemManager itemManager)
	{
		this.plugin = plugin;
		this.itemManager = itemManager;

		setLayout(new BorderLayout(0, 4));
		setBackground(ColorScheme.DARK_GRAY_COLOR);

		JPanel top = new JPanel(new GridLayout(0, 1, 0, 4));
		top.setBackground(ColorScheme.DARK_GRAY_COLOR);
		for (BossSetup s : plugin.getBosses())
		{
			setups.addItem(s);
		}
		setups.setFocusable(false);
		setups.addActionListener(e -> refresh());
		top.add(setups);

		JPanel totals = new JPanel(new GridLayout(1, 3, 4, 0));
		totals.setBackground(ColorScheme.DARK_GRAY_COLOR);
		totals.add(box("Budget", budget));
		totals.add(box("Mid", mid));
		totals.add(box("Best", best));
		top.add(totals);
		top.add(untradeables);

		JButton wiki = new JButton("Open wiki strategy page");
		wiki.setFocusable(false);
		wiki.addActionListener(e ->
		{
			BossSetup s = (BossSetup) setups.getSelectedItem();
			if (s != null)
			{
				LinkBrowser.browse(s.getUrl());
			}
		});
		top.add(wiki);
		top.setBorder(new EmptyBorder(0, 0, 4, 0));

		add(top, BorderLayout.NORTH);
		add(UiUtil.scroll(list), BorderLayout.CENTER);
		refresh();
	}

	void refresh()
	{
		list.removeAll();
		BossSetup setup = (BossSetup) setups.getSelectedItem();
		PriceBook prices = plugin.getPrices();
		GearPricer pricer = plugin.getGearPricer();

		if (setup == null)
		{
			list.add(UiUtil.emptyState("No boss data loaded."));
			repaintList();
			return;
		}
		addCheck(setup, !prices.isEmpty());
		addQuests(setup);
		if (prices.isEmpty())
		{
			list.add(UiUtil.emptyState("Fetching prices..."));
			repaintList();
			return;
		}

		Map<String, Gear.Owned> owned = plugin.isLoggedIn() ? plugin.getOwned() : java.util.Collections.emptyMap();
		long budgetTotal = 0;
		long midTotal = 0;
		long bestTotal = 0;
		List<String> unpriced = new ArrayList<>();

		for (BossSetup.Slot slot : setup.getSlots())
		{
			List<List<String>> tiers = slot.getTiers(); // best first
			int n = tiers.size();
			List<GearPricer.Price> priced = new ArrayList<>();
			for (List<String> tier : tiers)
			{
				priced.add(pricer.cheapestOf(tier, prices));
			}

			budgetTotal += cost(priced.get(n - 1));
			midTotal += cost(priced.get(n / 2));
			bestTotal += cost(priced.get(0));
			if (!priced.get(0).isTradeable())
			{
				unpriced.add(priced.get(0).getName());
			}

			list.add(UiUtil.header(slot.getName() + "  (weakest to strongest)"));
			// cheapest (worst) first, up to best in slot
			for (int i = n - 1; i >= 0; i--)
			{
				GearPricer.Price p = priced.get(i);
				List<String> alts = tiers.get(i);
				String title = String.join(" / ", alts);
				String tier = i == 0 ? "Best in slot" : i == n - 1 ? "Starter" : "Upgrade " + (n - 1 - i);
				String value = p.isTradeable() ? UiUtil.compact(p.getCost()) : "—";
				Color color = i == 0 ? UiUtil.PROFIT : p.isTradeable() ? ColorScheme.GRAND_EXCHANGE_PRICE : UiUtil.MUTED;
				String line3 = p.getNote() != null ? p.getNote() : alts.size() > 1 ? "Cheapest of these: " + p.getName() : null;
				Gear.Owned mine = BossCheck.ownedInTier(alts, owned);
				if (mine != null)
				{
					line3 = "You own this (" + mine.getWhere() + ")";
				}

				ItemRow row = new ItemRow(itemManager, p.getIconId(), title, value, color, tier, line3, tooltip(alts, p));
				if (mine != null)
				{
					row.setLine3Color(UiUtil.PROFIT);
				}
				else if (p.isTradeable())
				{
					String wanted = p.getName();
					row.action("Plan how to afford this", () -> plugin.planFor(wanted));
				}
				UiUtil.addRow(list, row);
			}
		}

		budget.setText(UiUtil.compact(budgetTotal));
		mid.setText(UiUtil.compact(midTotal));
		best.setText(UiUtil.compact(bestTotal));
		untradeables.setText(unpriced.isEmpty()
			? "Totals are GE prices for tradeable gear only."
			: "<html>Totals cover tradeable gear only. Best-in-slot also needs: "
				+ String.join(", ", unpriced) + "</html>");
		repaintList();
	}

	/**
	 * "Can you fight it?": your levels and quests against what the boss needs, and how much of
	 * the gear you already own. Needs you to be logged in.
	 */
	private void addCheck(BossSetup setup, boolean withGear)
	{
		List<BossCheck.SkillReq> skills = plugin.getBossCheck().skillsFor(setup.getBoss());
		BossQuests quests = plugin.getBossQuests();

		list.add(UiUtil.header("Can you fight it?"));
		JPanel box = new JPanel();
		box.setLayout(new BoxLayout(box, BoxLayout.Y_AXIS));
		box.setBackground(ColorScheme.DARKER_GRAY_COLOR);
		box.setBorder(new EmptyBorder(5, 6, 5, 6));

		if (!plugin.isLoggedIn())
		{
			StringBuilder sb = new StringBuilder("Log in to check your levels, quests and gear.");
			for (BossCheck.SkillReq r : skills)
			{
				sb.append("<br>Needs ").append(r.getLevel()).append(' ').append(pretty(r.getSkill()));
			}
			box.add(checkLine(sb.toString(), UiUtil.MUTED));
			UiUtil.addRow(list, box);
			return;
		}

		int missing = 0;
		for (BossCheck.SkillReq r : skills)
		{
			long[] have = plugin.getSkill(r.getSkill());
			boolean ok = have != null && have[0] >= r.getLevel();
			missing += ok ? 0 : 1;
			box.add(checkLine((ok ? "&#10003; " : "&#10007; ") + r.getLevel() + " " + pretty(r.getSkill())
				+ " (you: " + (have != null ? have[0] : "?") + ")"
				+ (r.getNote().isEmpty() ? "" : "<br><i>" + esc(r.getNote()) + "</i>"), ok ? UiUtil.PROFIT : UiUtil.LOSS));
		}

		LinkedHashSet<String> todo = new LinkedHashSet<>();
		boolean needsQuests = false;
		for (BossQuests.Req r : quests.forBoss(setup.getBoss()))
		{
			needsQuests = true;
			if (plugin.getQuestState(r.getQuest()) == QuestState.FINISHED)
			{
				continue;
			}
			for (String q : quests.lineFor(r.getQuest()))
			{
				if (plugin.getQuestState(q) != QuestState.FINISHED)
				{
					todo.add(q);
				}
			}
			todo.add(r.getQuest());
		}
		if (needsQuests)
		{
			missing += todo.isEmpty() ? 0 : 1;
			box.add(todo.isEmpty() ? checkLine("&#10003; Quests done", UiUtil.PROFIT)
				: checkLine("&#10007; " + todo.size() + (todo.size() == 1 ? " quest" : " quests") + " to do (listed below)", UiUtil.LOSS));
		}
		if (skills.isEmpty() && !needsQuests)
		{
			box.add(checkLine("&#10003; No level or quest needed", UiUtil.PROFIT));
		}

		if (withGear)
		{
			BossCheck.Kit kit = BossCheck.kit(setup, plugin.getGearPricer(), plugin.getPrices(), plugin.getOwned());
			StringBuilder sb = new StringBuilder("Gear: you own something for <b>").append(kit.getSlotsOwned())
				.append(" of ").append(kit.getSlots()).append("</b> slots");
			if (kit.getCostToFill() > 0)
			{
				sb.append("<br>About <b>").append(UiUtil.compact(kit.getCostToFill()))
					.append("</b> to fill the rest with the cheapest options");
			}
			if (!kit.getToEarn().isEmpty())
			{
				sb.append("<br>Can't be bought: ").append(esc(String.join(", ", kit.getToEarn())));
			}
			if (!plugin.isBankSeen())
			{
				sb.append("<br><i>Open your bank once so it's counted.</i>");
			}
			box.add(checkLine(sb.toString(), Color.WHITE));
		}

		JLabel verdict = UiUtil.label(missing == 0 ? "Yes, you meet the requirements" : "Not yet", missing == 0 ? UiUtil.PROFIT : IN_PROGRESS, true);
		verdict.setAlignmentX(LEFT_ALIGNMENT);
		verdict.setBorder(new EmptyBorder(0, 0, 3, 0));
		box.add(verdict, 0);
		UiUtil.addRow(list, box);
	}

	private static JLabel checkLine(String html, Color color)
	{
		JLabel l = UiUtil.label("<html><div style='width:" + QUEST_TEXT_WIDTH + "px'>" + html + "</div></html>", color, false);
		l.setAlignmentX(LEFT_ALIGNMENT);
		l.setBorder(new EmptyBorder(1, 0, 1, 0));
		return l;
	}

	private static String pretty(String skill)
	{
		return skill.isEmpty() ? skill : skill.charAt(0) + skill.substring(1).toLowerCase(Locale.ROOT);
	}

	/** Width the quest text wraps at, in HTML pixels (the side panel is narrow). */
	private static final int QUEST_TEXT_WIDTH = 140;
	private static final Color IN_PROGRESS = new Color(255, 200, 70);

	/**
	 * The quests this boss needs, each with everything to do before it, in order. Shows how far
	 * you are when logged in; click any quest to open its guide on the wiki.
	 */
	private void addQuests(BossSetup setup)
	{
		BossQuests data = plugin.getBossQuests();
		List<BossQuests.Req> reqs = data.forBoss(setup.getBoss());
		if (reqs.isEmpty())
		{
			return;
		}

		// the whole to-do list: each needed quest after the quests it needs, nothing twice
		LinkedHashSet<String> all = new LinkedHashSet<>();
		for (BossQuests.Req r : reqs)
		{
			all.addAll(data.lineFor(r.getQuest()));
			all.add(r.getQuest());
		}
		int done = 0;
		boolean known = false;
		for (String q : all)
		{
			QuestState s = plugin.getQuestState(q);
			known |= s != null;
			if (s == QuestState.FINISHED)
			{
				done++;
			}
		}

		list.add(UiUtil.header("Quests needed"));
		String summary = !known ? all.size() + (all.size() == 1 ? " quest" : " quests") + " · log in to see your progress"
			: done == all.size() ? "All done"
			: done + " of " + all.size() + " done · click a quest for its guide";
		JLabel top = UiUtil.label(summary, known && done == all.size() ? UiUtil.PROFIT : UiUtil.MUTED, false);
		top.setBorder(new EmptyBorder(0, 2, 4, 2));
		UiUtil.addRow(list, top);

		for (BossQuests.Req r : reqs)
		{
			QuestState state = plugin.getQuestState(r.getQuest());
			UiUtil.addRow(list, questRow(r.getQuest(), r.getNote(), state, true, 0));
			// once the quest itself is done there's no point listing what led up to it
			if (state == QuestState.FINISHED)
			{
				continue;
			}
			int step = 0;
			for (String q : data.lineFor(r.getQuest()))
			{
				UiUtil.addRow(list, questRow(q, "", plugin.getQuestState(q), false, ++step));
			}
		}
	}

	private JLabel questRow(String quest, String note, QuestState state, boolean main, int step)
	{
		String mark = state == QuestState.FINISHED ? "&#10003; " : step > 0 ? step + ". " : "";
		StringBuilder sb = new StringBuilder("<html><div style='width:").append(QUEST_TEXT_WIDTH).append("px'>")
			.append(main ? "<b>" : "").append(mark).append(esc(quest)).append(main ? "</b>" : "");
		if (state == QuestState.IN_PROGRESS)
		{
			sb.append(" (started)");
		}
		if (!note.isEmpty())
		{
			sb.append("<br><i>").append(esc(note)).append("</i>");
		}
		sb.append("</div></html>");

		Color color = state == QuestState.FINISHED ? UiUtil.PROFIT : state == QuestState.IN_PROGRESS ? IN_PROGRESS
			: main ? Color.WHITE : UiUtil.MUTED;
		JLabel row = UiUtil.label(sb.toString(), color, false);
		row.setBorder(new EmptyBorder(1, main ? 2 : 10, 1, 2));
		row.setCursor(Cursor.getPredefinedCursor(Cursor.HAND_CURSOR));
		row.setToolTipText("Open the " + quest + " guide on the OSRS Wiki");
		row.addMouseListener(new MouseAdapter()
		{
			@Override
			public void mousePressed(MouseEvent e)
			{
				if (e.getButton() == MouseEvent.BUTTON1)
				{
					LinkBrowser.browse(BossQuests.wikiUrl(quest));
				}
			}
		});
		return row;
	}

	private static String esc(String s)
	{
		return s.replace("&", "&amp;").replace("<", "&lt;").replace(">", "&gt;");
	}

	private static long cost(GearPricer.Price p)
	{
		return p != null && p.isTradeable() ? p.getCost() : 0;
	}

	private static String tooltip(List<String> alts, GearPricer.Price p)
	{
		StringBuilder sb = new StringBuilder("<html>");
		sb.append(alts.size() > 1 ? "Equally good options:<br>" : "");
		for (String a : alts)
		{
			sb.append("• ").append(a.replace("&", "&amp;")).append("<br>");
		}
		if (p.isTradeable())
		{
			sb.append("Cheapest: ").append(p.getName()).append(" ≈ ").append(UiUtil.gp(p.getCost())).append(" gp");
		}
		if (p.getNote() != null)
		{
			sb.append("<br>").append(p.getNote());
		}
		return sb.append("</html>").toString();
	}

	private static JLabel stat()
	{
		return UiUtil.label("-", Color.WHITE, true);
	}

	private static JPanel box(String title, JLabel value)
	{
		JPanel p = new JPanel(new GridLayout(2, 1));
		p.setBackground(ColorScheme.DARKER_GRAY_COLOR);
		p.setBorder(new EmptyBorder(4, 6, 4, 6));
		p.add(UiUtil.label(title, UiUtil.MUTED, false));
		p.add(value);
		return p;
	}

	private void repaintList()
	{
		list.revalidate();
		list.repaint();
	}
}

package com.moneymaker.ui;

import com.moneymaker.MoneyMakerConfig;
import com.moneymaker.MoneyMakerPlugin;
import com.moneymaker.data.FarmRoute;
import com.moneymaker.data.FarmRun;
import com.moneymaker.data.JobResult;
import com.moneymaker.data.PriceBook;
import java.awt.BorderLayout;
import java.awt.Color;
import java.awt.Cursor;
import java.awt.GridLayout;
import java.awt.event.MouseAdapter;
import java.awt.event.MouseEvent;
import java.util.ArrayList;
import java.util.Comparator;
import java.util.HashMap;
import java.util.List;
import java.util.Locale;
import java.util.Map;
import java.util.Set;
import java.util.TreeSet;
import javax.swing.BoxLayout;
import javax.swing.JComboBox;
import javax.swing.JLabel;
import javax.swing.JPanel;
import javax.swing.Timer;
import javax.swing.border.EmptyBorder;
import net.runelite.client.game.ItemManager;
import net.runelite.client.ui.ColorScheme;
import net.runelite.client.util.LinkBrowser;

/** Farm runs, bird houses and dailies: the best runs at live prices, with timers. */
class FarmPanel extends JPanel
{
	private static final String ALL = "All runs";
	private static final String[] SORTS = {"Profit per run", "Profit per hour", "XP per run", "Ready soonest"};
	private static final Color WAITING = new Color(255, 200, 70);
	/** Width the route text wraps at, in HTML pixels (the side panel is narrow). */
	private static final int ROUTE_TEXT_WIDTH = 140;

	private final MoneyMakerPlugin plugin;
	private final ItemManager itemManager;
	private final JComboBox<String> group = new JComboBox<>();
	private final JComboBox<String> sort = new JComboBox<>(SORTS);
	private final JLabel status = UiUtil.label(" ", UiUtil.MUTED, false);
	private final JPanel list = UiUtil.verticalList();
	private final Timer tick;
	/** Runs whose route is open under their row (by run id). */
	private final Set<String> openRoutes = new java.util.HashSet<>();
	/** Stops you've ticked off on each run (by run id), until you start its timer. */
	private final Map<String, Set<Integer>> visited = new HashMap<>();
	/** Rows on screen, so the timers can tick without rebuilding the list. */
	private final Map<FarmRun, ItemRow> rows = new HashMap<>();

	FarmPanel(MoneyMakerPlugin plugin, ItemManager itemManager)
	{
		this.plugin = plugin;
		this.itemManager = itemManager;
		setLayout(new BorderLayout(0, 4));
		setBackground(ColorScheme.DARK_GRAY_COLOR);

		JPanel controls = new JPanel(new GridLayout(0, 1, 0, 4));
		controls.setBackground(ColorScheme.DARK_GRAY_COLOR);
		controls.setBorder(new EmptyBorder(0, 0, 2, 0));

		TreeSet<String> groups = new TreeSet<>();
		for (FarmRun r : plugin.getFarmRuns())
		{
			groups.add(r.getGroup());
		}
		group.addItem(ALL);
		for (String g : groups)
		{
			group.addItem(g);
		}
		group.setFocusable(false);
		group.addActionListener(e -> refresh());
		sort.setFocusable(false);
		sort.addActionListener(e -> refresh());
		controls.add(group);
		controls.add(sort);
		controls.add(status);

		add(controls, BorderLayout.NORTH);
		add(UiUtil.scroll(list), BorderLayout.CENTER);

		// tick the countdowns while the panel is open
		tick = new Timer(15_000, e ->
		{
			if (isShowing())
			{
				refreshTimers();
			}
		});
		tick.start();
		refresh();
	}

	void refresh()
	{
		list.removeAll();
		rows.clear();
		PriceBook prices = plugin.getPrices();
		MoneyMakerConfig config = plugin.getConfig();
		if (prices.isEmpty())
		{
			status.setText(plugin.getPriceError() != null ? "Couldn't load prices" : "Loading prices...");
			list.add(UiUtil.emptyState("Fetching prices..."));
			repaintList();
			return;
		}

		String g = (String) group.getSelectedItem();
		List<FarmRun.Priced> runs = new ArrayList<>();
		for (FarmRun r : plugin.getFarmRuns())
		{
			if (g != null && !ALL.equals(g) && !g.equals(r.getGroup()))
			{
				continue;
			}
			if (!config.includeMembers() && r.isMembers())
			{
				continue;
			}
			FarmRun.Priced p = r.price(prices, config.priceMode());
			if (p != null)
			{
				runs.add(p);
			}
		}

		// runs with a timer going come first, then the chosen sort
		Comparator<FarmRun.Priced> bySort = comparator();
		runs.sort(Comparator.comparing((FarmRun.Priced p) -> plugin.getPlanted(p.getRun()) == 0).thenComparing(bySort));

		int timers = 0;
		for (FarmRun.Priced p : runs)
		{
			if (plugin.getPlanted(p.getRun()) != 0)
			{
				timers++;
			}
			ItemRow row = row(p);
			rows.put(p.getRun(), row);
			UiUtil.addRow(list, row);
			if (openRoutes.contains(p.getRun().getId()))
			{
				UiUtil.addRow(list, routePanel(p.getRun()));
			}
		}
		status.setText(runs.size() + " runs · " + timers + " timer" + (timers == 1 ? "" : "s") + " · click a run for its timer and route");
		if (runs.isEmpty())
		{
			list.add(UiUtil.emptyState("No runs match."));
		}
		refreshTimers();
		repaintList();
	}

	void stop()
	{
		tick.stop();
	}

	/** Update the countdown line on each row. */
	void refreshTimers()
	{
		long now = System.currentTimeMillis();
		for (Map.Entry<FarmRun, ItemRow> e : rows.entrySet())
		{
			FarmRun r = e.getKey();
			ItemRow row = e.getValue();
			long ready = plugin.getReadyAt(r);
			long[] skill = r.hasSkill() ? plugin.getSkill(r.getSkill()) : null;
			if (ready == 0)
			{
				if (skill != null && skill[0] < r.getLevel())
				{
					row.setLine3("Needs " + r.getLevel() + " " + pretty(r.getSkill()) + " (you: " + skill[0] + ")");
					row.setLine3Color(UiUtil.LOSS);
				}
				else
				{
					row.setLine3("No timer · click when you've planted");
					row.setLine3Color(UiUtil.MUTED);
				}
			}
			else if (now < ready)
			{
				row.setLine3("Ready in " + left(ready - now));
				row.setLine3Color(WAITING);
			}
			else
			{
				row.setLine3("Ready now!");
				row.setLine3Color(UiUtil.PROFIT);
			}
		}
	}

	private Comparator<FarmRun.Priced> comparator()
	{
		switch (Math.max(0, sort.getSelectedIndex()))
		{
			case 1:
				return Comparator.comparingLong(FarmRun.Priced::getProfitPerHour).reversed();
			case 2:
				return Comparator.comparingDouble((FarmRun.Priced p) -> p.getRun().getXp()).reversed();
			case 3:
				return Comparator.comparingLong((FarmRun.Priced p) ->
				{
					long ready = plugin.getReadyAt(p.getRun());
					return ready == 0 ? Long.MAX_VALUE : ready;
				});
			default:
				return Comparator.comparingLong(FarmRun.Priced::getProfit).reversed();
		}
	}

	private ItemRow row(FarmRun.Priced p)
	{
		FarmRun r = p.getRun();
		int icon = !p.getSell().isEmpty() ? p.getSell().get(0).getItemId() : !p.getBuy().isEmpty() ? p.getBuy().get(0).getItemId() : -1;
		long profit = p.getProfit();
		String line2 = (r.getXp() > 0 ? UiUtil.compact(Math.round(r.getXp())) + " xp · " : "")
			+ "cost " + UiUtil.compact(Math.max(0, p.getCost())) + " · " + grow(r.getGrowMinutes());
		ItemRow row = new ItemRow(itemManager, icon, r.getName(), UiUtil.signedGp(profit), UiUtil.profitColor(profit),
			line2, " ", tooltip(p));
		List<FarmRoute.Stop> stops = plugin.getFarmRoute().stopsFor(r);
		if (!stops.isEmpty())
		{
			boolean open = openRoutes.contains(r.getId());
			row.action(open ? "Hide route" : "Show route (" + stops.size() + " stops)", () ->
			{
				if (!openRoutes.remove(r.getId()))
				{
					openRoutes.add(r.getId());
				}
				refresh();
			});
		}
		row.action("Start timer (planted now)", () ->
		{
			// run done: clear the ticks ready for next time
			visited.remove(r.getId());
			plugin.startFarmTimer(r);
		});
		if (plugin.getPlanted(r) != 0)
		{
			row.action("Clear timer", () -> plugin.clearFarmTimer(r));
		}
		if (!r.getUrl().isEmpty())
		{
			row.action("Open wiki page", () -> LinkBrowser.browse(r.getUrl()));
		}
		return row;
	}

	private String tooltip(FarmRun.Priced p)
	{
		FarmRun r = p.getRun();
		StringBuilder sb = new StringBuilder("<html><b>").append(esc(r.getName())).append("</b>");
		if (r.hasSkill())
		{
			sb.append("<br>Needs ").append(r.getLevel()).append(' ').append(pretty(r.getSkill()));
			if (r.getXp() > 0)
			{
				sb.append(" · ").append(UiUtil.gp(Math.round(r.getXp()))).append(" xp per run");
			}
		}
		sb.append("<br>Grows in ").append(grow(r.getGrowMinutes())).append(" · about ")
			.append(Math.max(1, Math.round(r.getRunMinutes()))).append(" min to do");
		if (r.getPatches() > 0)
		{
			sb.append(" · ").append(r.getPatches()).append(" patches");
		}
		sb.append("<br><br><b>Buy (per run)</b>");
		for (JobResult.Line l : p.getBuy())
		{
			sb.append("<br>").append(qty(l.getQty())).append(" × ").append(esc(l.getItem())).append(" @ ").append(UiUtil.gp(l.getPriceEach()));
		}
		if (r.getCoins() > 0)
		{
			sb.append("<br>+ ").append(UiUtil.gp(Math.round(r.getCoins()))).append(" coins");
		}
		sb.append("<br><b>Get</b>");
		if (r.getCoins() < 0)
		{
			sb.append("<br>").append(UiUtil.gp(Math.round(-r.getCoins()))).append(" coins (or loot valued in coins)");
		}
		for (JobResult.Line l : p.getSell())
		{
			sb.append("<br>").append(qty(l.getQty())).append(" × ").append(esc(l.getItem())).append(" @ ").append(UiUtil.gp(l.getPriceEach()));
		}
		sb.append("<br>Cash needed: ").append(UiUtil.gp(Math.max(0, p.getCost())));
		sb.append("<br>Profit per run after 2% tax: <b>").append(UiUtil.signedGp(p.getProfit())).append("</b>");
		sb.append("<br>= ").append(UiUtil.signedGp(p.getProfitPerHour())).append(" per real hour if you do it every time it's ready");
		List<FarmRoute.Stop> stops = plugin.getFarmRoute().stopsFor(r);
		if (!stops.isEmpty())
		{
			sb.append("<br><br><b>Route</b> (click the run to open it)");
			for (int i = 0; i < stops.size(); i++)
			{
				sb.append("<br>").append(i + 1).append(". ").append(esc(stops.get(i).getName()));
			}
		}
		if (!r.getNote().isEmpty())
		{
			sb.append("<br><br><i>").append(esc(r.getNote())).append("</i>");
		}
		sb.append("<br><br>Click for the timer and the route.</html>");
		return sb.toString();
	}

	/** The stops for a run, in order. Click a stop to tick it off as you go. */
	private JPanel routePanel(FarmRun run)
	{
		List<FarmRoute.Stop> stops = plugin.getFarmRoute().stopsFor(run);
		Set<Integer> done = visited.computeIfAbsent(run.getId(), k -> new java.util.HashSet<>());

		JPanel box = new JPanel();
		box.setLayout(new BoxLayout(box, BoxLayout.Y_AXIS));
		box.setBackground(ColorScheme.DARKER_GRAY_COLOR);
		box.setBorder(new EmptyBorder(4, 8, 6, 6));

		JLabel title = UiUtil.label(done.size() + " of " + stops.size() + " done · click a stop to tick it off", UiUtil.MUTED, false);
		title.setAlignmentX(LEFT_ALIGNMENT);
		title.setBorder(new EmptyBorder(0, 0, 4, 0));
		box.add(title);

		for (int i = 0; i < stops.size(); i++)
		{
			final int index = i;
			FarmRoute.Stop s = stops.get(i);
			boolean ticked = done.contains(i);

			// a fixed width makes the text wrap inside the side panel instead of running off the edge
			StringBuilder sb = new StringBuilder("<html><div style='width:")
				.append(ROUTE_TEXT_WIDTH).append("px'><b>")
				.append(ticked ? "&#10003; " : (i + 1) + ". ").append(esc(s.getName())).append("</b>");
			if (!ticked)
			{
				if (!s.getTravel().isEmpty())
				{
					sb.append("<br>").append(esc(s.getTravel()));
				}
				if (!s.getNeeds().isEmpty())
				{
					sb.append("<br><i>Needs: ").append(esc(s.getNeeds())).append("</i>");
				}
			}
			sb.append("</div></html>");

			JLabel stop = UiUtil.label(sb.toString(), ticked ? UiUtil.PROFIT : Color.WHITE, false);
			stop.setAlignmentX(LEFT_ALIGNMENT);
			stop.setBorder(new EmptyBorder(3, 0, 3, 0));
			stop.setCursor(Cursor.getPredefinedCursor(Cursor.HAND_CURSOR));
			stop.setToolTipText(ticked ? "Click to untick" : "Click when you've done this stop");
			stop.addMouseListener(new MouseAdapter()
			{
				@Override
				public void mousePressed(MouseEvent e)
				{
					if (e.getButton() != MouseEvent.BUTTON1)
					{
						return;
					}
					if (!done.remove(index))
					{
						done.add(index);
					}
					refresh();
				}
			});
			box.add(stop);
		}
		return box;
	}

	private static String left(long ms)
	{
		long mins = (ms + 59_999) / 60_000;
		if (mins >= 24 * 60)
		{
			return (mins / 1440) + "d " + (mins % 1440) / 60 + "h";
		}
		return mins >= 60 ? (mins / 60) + "h " + (mins % 60) + "m" : mins + "m";
	}

	private static String grow(double minutes)
	{
		long m = Math.round(minutes);
		if (m < 60)
		{
			return m + "m";
		}
		if (m < 48 * 60)
		{
			return (m / 60) + "h" + (m % 60 == 0 ? "" : " " + (m % 60) + "m");
		}
		return String.format(Locale.ROOT, "%.1f days", m / 1440.0);
	}

	private static String qty(double v)
	{
		return v == Math.rint(v) ? UiUtil.gp((long) v) : String.format(Locale.ROOT, "%.2f", v);
	}

	private static String pretty(String skill)
	{
		return skill.charAt(0) + skill.substring(1).toLowerCase(Locale.ROOT);
	}

	private static String esc(String s)
	{
		return s.replace("&", "&amp;").replace("<", "&lt;").replace(">", "&gt;");
	}

	private void repaintList()
	{
		list.revalidate();
		list.repaint();
	}
}

