import javax.swing.event.DocumentEvent;
import javax.swing.event.DocumentListener;
import net.runelite.client.game.ItemManager;
import net.runelite.client.ui.ColorScheme;
import net.runelite.client.ui.components.IconTextField;
import net.runelite.client.util.LinkBrowser;

/**
 * Pick something you want (an item to buy, or a level to reach) and see what it costs, how much
 * you still need, and the quickest jobs you can do to pay for it.
 */
class GoalPanel extends JPanel
{
	private static final String ITEM = "Buy an item";
	private static final String LEVEL = "Reach a level";
	private static final int MAX_MATCHES = 8;
	private static final int MAX_EARNERS = 5;
	/** Width the summary text wraps at, in HTML pixels (the side panel is narrow). */
	private static final int TEXT_WIDTH = 145;

	private final MoneyMakerPlugin plugin;
	private final ItemManager itemManager;
	private final JComboBox<String> mode = new JComboBox<>(new String[]{ITEM, LEVEL});
	private final IconTextField search = new IconTextField();
	private final JComboBox<String> skill = new JComboBox<>();
	private final JSpinner level = new JSpinner(new SpinnerNumberModel(70, 2, 99, 1));
	private final JPanel inputs = new JPanel(new CardLayout());
	private final JPanel list = UiUtil.verticalList();
	private final Timer searchDelay = new Timer(250, e -> refresh());

	/** The item you're saving for, or null. Remembered between sessions. */
	private String goalItem;
	/** True while the controls are being filled in by code, so that doesn't count as you changing them. */
	private boolean updating;

	GoalPanel(MoneyMakerPlugin plugin, ItemManager itemManager)
	{
		this.plugin = plugin;
		this.itemManager = itemManager;
		setLayout(new BorderLayout(0, 4));
		setBackground(ColorScheme.DARK_GRAY_COLOR);

		JPanel controls = new JPanel();
		controls.setLayout(new BoxLayout(controls, BoxLayout.Y_AXIS));
		controls.setBackground(ColorScheme.DARK_GRAY_COLOR);
		controls.setBorder(new EmptyBorder(0, 0, 2, 0));

		mode.setFocusable(false);
		controls.add(mode);
		controls.add(javax.swing.Box.createRigidArea(new Dimension(0, 4)));

		search.setIcon(IconTextField.Icon.SEARCH);
		search.setPreferredSize(new Dimension(0, 30));
		search.setBackground(ColorScheme.DARKER_GRAY_COLOR);
		search.setHoverBackgroundColor(ColorScheme.DARK_GRAY_HOVER_COLOR);
		search.getDocument().addDocumentListener(new DocumentListener()
		{
			@Override
			public void insertUpdate(DocumentEvent e)
			{
				searchDelay.restart();
			}

			@Override
			public void removeUpdate(DocumentEvent e)
			{
				searchDelay.restart();
			}

			@Override
			public void changedUpdate(DocumentEvent e)
			{
				searchDelay.restart();
			}
		});
		searchDelay.setRepeats(false);

		JPanel levelRow = new JPanel(new BorderLayout(4, 0));
		levelRow.setBackground(ColorScheme.DARK_GRAY_COLOR);
		for (String s : plugin.getTraining().getSkills())
		{
			skill.addItem(s);
		}
		skill.setRenderer(new javax.swing.DefaultListCellRenderer()
		{
			@Override
			public java.awt.Component getListCellRendererComponent(javax.swing.JList<?> l, Object value, int index, boolean sel, boolean focus)
			{
				super.getListCellRendererComponent(l, value, index, sel, focus);
				if (value != null)
				{
					setText(pretty(value.toString()));
				}
				return this;
			}
		});
		skill.setFocusable(false);
		levelRow.add(skill, BorderLayout.CENTER);
		levelRow.add(level, BorderLayout.EAST);

		inputs.setBackground(ColorScheme.DARK_GRAY_COLOR);
		inputs.add(search, ITEM);
		inputs.add(levelRow, LEVEL);
		controls.add(inputs);

		add(controls, BorderLayout.NORTH);
		add(UiUtil.scroll(list), BorderLayout.CENTER);

		// pick up where you left off
		updating = true;
		goalItem = emptyToNull(plugin.getSaved("goalItem"));
		if (LEVEL.equals(plugin.getSaved("goalMode")))
		{
			mode.setSelectedItem(LEVEL);
		}
		String savedSkill = plugin.getSaved("goalSkill");
		if (savedSkill != null)
		{
			skill.setSelectedItem(savedSkill);
		}
		try
		{
			String savedLevel = plugin.getSaved("goalLevel");
			if (savedLevel != null)
			{
				level.setValue(Math.max(2, Math.min(99, Integer.parseInt(savedLevel))));
			}
		}
		catch (NumberFormatException ignored)
		{
			// keep the default
		}
		updating = false;
		showInputs();

		mode.addActionListener(e -> changed());
		skill.addActionListener(e -> changed());
		level.addChangeListener(e -> changed());
		refresh();
	}

	/** Set the item to save for (used by "Plan how to afford this" on the Boss tab). */
	void setItem(String name)
	{
		goalItem = emptyToNull(name);
		plugin.save("goalItem", goalItem);
		updating = true;
		mode.setSelectedItem(ITEM);
		search.setText("");
		updating = false;
		plugin.save("goalMode", ITEM);
		showInputs();
		searchDelay.stop();
		refresh();
	}

	private void changed()
	{
		if (updating)
		{
			return;
		}
		plugin.save("goalMode", (String) mode.getSelectedItem());
		plugin.save("goalSkill", (String) skill.getSelectedItem());
		plugin.save("goalLevel", String.valueOf(level.getValue()));
		showInputs();
		refresh();
	}

	private void showInputs()
	{
		((CardLayout) inputs.getLayout()).show(inputs, (String) mode.getSelectedItem());
	}

	void refresh()
	{
		list.removeAll();
		PriceBook prices = plugin.getPrices();
		if (prices.isEmpty())
		{
			list.add(UiUtil.emptyState(plugin.getPriceError() != null
				? "Couldn't reach the OSRS Wiki price API." : "Fetching prices..."));
			repaintList();
			return;
		}
		if (LEVEL.equals(mode.getSelectedItem()))
		{
			levelGoal(prices);
		}
		else
		{
			itemGoal(prices);
		}
		repaintList();
	}

	// ---------------------------------------------------------------- buying an item

	private void itemGoal(PriceBook prices)
	{
		String q = search.getText() == null ? "" : search.getText().trim();
		if (!q.isEmpty())
		{
			List<ItemPrice> matches = prices.search(q, MAX_MATCHES);
			list.add(UiUtil.header("Pick an item"));
			if (matches.isEmpty())
			{
				list.add(UiUtil.emptyState("Nothing on the GE matches \"" + esc(q) + "\"."));
			}
			for (ItemPrice p : matches)
			{
				ItemRow row = new ItemRow(itemManager, p.getId(), p.getName(), UiUtil.compact(p.typical()),
					ColorScheme.GRAND_EXCHANGE_PRICE, "Click to make this your goal", null, null);
				row.onClick(() -> setItem(p.getName()));
				UiUtil.addRow(list, row);
			}
			return;
		}
		if (goalItem == null)
		{
			list.add(UiUtil.emptyState("Search for something you want to buy.<br><br>"
				+ "Or click a piece of gear on the <b>Boss</b> tab and choose <b>Plan how to afford this</b>."));
			return;
		}

		GearPricer.Price price = plugin.getGearPricer().price(goalItem, prices);
		list.add(UiUtil.header("Your goal"));
		if (!price.isTradeable() || price.getCost() <= 0)
		{
			list.add(UiUtil.emptyState("<b>" + esc(goalItem) + "</b> can't be bought on the GE right now."
				+ (price.getNote() != null ? "<br>" + esc(price.getNote()) : "")));
			addClear();
			return;
		}

		long cost = price.getCost();
		ItemRow goal = new ItemRow(itemManager, price.getIconId(), goalItem, UiUtil.compact(cost),
			ColorScheme.GRAND_EXCHANGE_PRICE, UiUtil.gp(cost) + " gp", price.getNote(), null);
		UiUtil.addRow(list, goal);

		Map<String, Gear.Owned> owned = plugin.getOwned();
		Gear.Owned mine = plugin.isLoggedIn() ? BossCheck.owned(goalItem, owned) : null;
		if (mine != null)
		{
			UiUtil.addRow(list, text("You already own this (" + mine.getWhere() + ").", UiUtil.PROFIT));
			addClear();
			return;
		}
		long need = addMoney(cost, owned);
		if (need > 0)
		{
			addEarners(prices, need, 0);
		}
		addClear();
	}

	// ---------------------------------------------------------------- reaching a level

	private void levelGoal(PriceBook prices)
	{
		String sk = (String) skill.getSelectedItem();
		if (sk == null)
		{
			list.add(UiUtil.emptyState("No training data loaded."));
			return;
		}
		int target = (Integer) level.getValue();
		long[] mine = plugin.getSkill(sk);
		int fromLevel = mine != null ? (int) mine[0] : 1;
		long fromXp = mine != null ? mine[1] : 0;

		list.add(UiUtil.header("Your goal"));
		if (fromLevel >= target)
		{
			UiUtil.addRow(list, text("You're already level " + fromLevel + " " + pretty(sk) + ". Pick a higher level.", UiUtil.PROFIT));
			return;
		}

		MoneyMakerConfig config = plugin.getConfig();
		boolean iron = plugin.isIronman();
		Training.Filter filter = new Training.Filter();
		filter.ironman = iron;
		filter.members = config.includeMembers();
		List<Training.Step> steps = plugin.getTraining().plan(sk, fromXp, target, filter);
		if (steps.isEmpty())
		{
			list.add(UiUtil.emptyState("No training methods found for " + pretty(sk) + " at level " + fromLevel + "."));
			return;
		}
		double trainHours = GoalPlan.hours(steps);
		long cost = iron ? 0 : GoalPlan.suppliesCost(steps, prices, config.priceMode());

		StringBuilder sb = new StringBuilder("<b>").append(pretty(sk)).append(' ').append(fromLevel).append(" → ").append(target).append("</b>");
		sb.append("<br>Training: about ").append(time(trainHours)).append(" on the fastest route (see the Train tab)");
		if (mine == null)
		{
			sb.append("<br><i>Log in to start from your own level.</i>");
		}
		UiUtil.addRow(list, text(sb.toString(), Color.WHITE));

		if (iron)
		{
			UiUtil.addRow(list, text("Ironman mode: you gather the supplies yourself, so there's nothing to buy.", UiUtil.MUTED));
			return;
		}
		if (cost <= 0)
		{
			UiUtil.addRow(list, text("This route has no supplies to buy.", UiUtil.PROFIT));
			return;
		}
		long need = addMoney(cost, plugin.getOwned());
		if (need > 0)
		{
			addEarners(prices, need, trainHours);
		}
	}

	// ---------------------------------------------------------------- shared

	/** Show what it costs, what you have and what's left. Returns how much you still need. */
	private long addMoney(long cost, Map<String, Gear.Owned> owned)
	{
		StringBuilder sb = new StringBuilder("Costs about <b>").append(UiUtil.compact(cost)).append("</b>");
		long need = cost;
		if (plugin.isLoggedIn())
		{
			long have = GoalPlan.coins(owned);
			need = Math.max(0, cost - have);
			sb.append("<br>You have ").append(UiUtil.compact(have))
				.append(plugin.isBankSeen() ? " (bag and bank)" : " (bag only: open your bank once to count it)");
		}
		else
		{
			sb.append("<br><i>Log in to count the coins you already have.</i>");
		}
		UiUtil.addRow(list, text(sb.toString(), Color.WHITE));
		UiUtil.addRow(list, need > 0
			? text("Still need <b>" + UiUtil.compact(need) + "</b>", new Color(255, 200, 70))
			: text("You can afford it now.", UiUtil.PROFIT));
		return need;
	}

	/** The quickest jobs you can do right now to earn the amount. */
	private void addEarners(PriceBook prices, long need, double extraHours)
	{
		if (plugin.isIronman())
		{
			list.add(UiUtil.emptyState("Ironman mode: GE money makers don't apply to you."));
			return;
		}
		MoneyMakerConfig config = plugin.getConfig();
		List<JobResult> jobs = new ArrayList<>();
		for (Recipe r : plugin.getRecipes())
		{
			if (!config.includeMembers() && r.isMembers())
			{
				continue;
			}
			if (!plugin.meetsReqs(r))
			{
				continue;
			}
			jobs.add(JobResult.evaluate(r, prices, config.priceMode(), config.speed(), 0, -1, -1));
		}
		List<GoalPlan.Earner> earners = GoalPlan.earners(jobs, need, MAX_EARNERS);

		list.add(UiUtil.header("Fastest ways to earn it"));
		if (earners.isEmpty())
		{
			list.add(UiUtil.emptyState("No money makers found that you can do."));
			return;
		}
		if (extraHours > 0)
		{
			UiUtil.addRow(list, text("About <b>" + time(extraHours + earners.get(0).getHours())
				+ "</b> in total: earning the money with the best job, then training.", UiUtil.MUTED));
		}
		for (GoalPlan.Earner e : earners)
		{
			JobResult j = e.getJob();
			Recipe rec = j.getRecipe();
			int icon = j.getOutputLines().isEmpty() ? -1 : j.getOutputLines().get(0).getItemId();
			ItemRow row = new ItemRow(itemManager, icon, rec.getName(), time(e.getHours()), Color.WHITE,
				UiUtil.signedGp(j.getGpPerHour()) + "/h", rec.getCategory() + (plugin.isLoggedIn() ? "" : " · log in to check levels"), null);
			if (!rec.getUrl().isEmpty())
			{
				row.action("Open wiki guide", () -> LinkBrowser.browse(rec.getUrl()));
			}
			UiUtil.addRow(list, row);
		}
	}

	private void addClear()
	{
		JButton clear = new JButton("Clear goal");
		clear.setFocusable(false);
		clear.addActionListener(e -> setItem(null));
		JPanel wrap = new JPanel(new GridLayout(1, 1));
		wrap.setBackground(ColorScheme.DARK_GRAY_COLOR);
		wrap.setBorder(new EmptyBorder(6, 0, 0, 0));
		wrap.add(clear);
		UiUtil.addRow(list, wrap);
	}

	/** A wrapped block of text on a card. */
	private static JLabel text(String html, Color color)
	{
		JLabel l = UiUtil.label("<html><div style='width:" + TEXT_WIDTH + "px'>" + html + "</div></html>", color, false);
		l.setOpaque(true);
		l.setBackground(ColorScheme.DARKER_GRAY_COLOR);
		l.setBorder(new EmptyBorder(5, 6, 5, 6));
		return l;
	}

	/** 45m, 12h 30m, 3d 4h */
	static String time(double hours)
	{
		long mins = Math.max(1, Math.round(hours * 60));
		if (mins < 60)
		{
			return mins + "m";
		}
		if (mins < 48 * 60)
		{
			return (mins / 60) + "h" + (mins % 60 == 0 ? "" : " " + (mins % 60) + "m");
		}
		return (mins / 1440) + "d " + (mins % 1440) / 60 + "h";
	}

	private static String emptyToNull(String s)
	{
		return s == null || s.trim().isEmpty() ? null : s.trim();
	}

	private static String pretty(String skill)
	{
		return skill.isEmpty() ? skill : skill.charAt(0) + skill.substring(1).toLowerCase(Locale.ROOT);
	}

	private static String esc(String s)
	{
		return s.replace("&", "&amp;").replace("<", "&lt;").replace(">", "&gt;");
	}

	private void repaintList()
	{
		list.revalidate();
		list.repaint();
	}
}

package com.moneymaker.ui;

import java.awt.BorderLayout;
import java.awt.Color;
import java.awt.Dimension;
import java.awt.GridLayout;
import java.awt.event.MouseAdapter;
import java.awt.event.MouseEvent;
import javax.swing.JLabel;
import javax.swing.JMenuItem;
import javax.swing.JPanel;
import javax.swing.JPopupMenu;
import javax.swing.SwingConstants;
import javax.swing.border.EmptyBorder;
import net.runelite.client.game.ItemManager;
import net.runelite.client.ui.ColorScheme;

/** One row in a list: item icon, a title line with a coloured value, and two detail lines. */
class ItemRow extends JPanel
{
	private final JPopupMenu menu = new JPopupMenu();
	private JLabel line3Label;
	/** What a left click does, instead of opening the menu. Null for the menu. */
	private Runnable click;

	ItemRow(ItemManager itemManager, int itemId, String title, String value, Color valueColor,
		String line2, String line3, String tooltip)
	{
		setLayout(new BorderLayout(6, 0));
		setBackground(ColorScheme.DARKER_GRAY_COLOR);
		setBorder(new EmptyBorder(5, 5, 5, 6));

		JLabel icon = new JLabel();
		icon.setPreferredSize(new Dimension(36, 32));
		icon.setHorizontalAlignment(SwingConstants.CENTER);
		if (itemManager != null && itemId > 0)
		{
			itemManager.getImage(itemId).addTo(icon);
		}
		add(icon, BorderLayout.WEST);

		JPanel lines = new JPanel(new GridLayout(line3 == null ? 2 : 3, 1, 0, 1));
		lines.setOpaque(false);
		lines.setMinimumSize(new Dimension(0, 0));

		JPanel top = new JPanel(new BorderLayout(4, 0));
		top.setOpaque(false);
		top.add(UiUtil.label(title, Color.WHITE, false), BorderLayout.CENTER);
		if (value != null)
		{
			top.add(UiUtil.label(value, valueColor, false), BorderLayout.EAST);
		}
		lines.add(top);
		lines.add(UiUtil.label(line2, UiUtil.MUTED, false));
		if (line3 != null)
		{
			line3Label = UiUtil.label(line3, UiUtil.MUTED, false);
			lines.add(line3Label);
		}
		add(lines, BorderLayout.CENTER);

		if (tooltip != null)
		{
			setToolTipText(tooltip);
		}

		addMouseListener(new MouseAdapter()
		{
			@Override
			public void mouseEntered(MouseEvent e)
			{
				setBackground(ColorScheme.DARKER_GRAY_HOVER_COLOR);
			}

			@Override
			public void mouseExited(MouseEvent e)
			{
				setBackground(ColorScheme.DARKER_GRAY_COLOR);
			}

			@Override
			public void mousePressed(MouseEvent e)
			{
				if (e.getButton() == MouseEvent.BUTTON1 && click != null)
				{
					click.run();
				}
				else if (e.isPopupTrigger() || e.getButton() == MouseEvent.BUTTON1)
				{
					showMenu(e);
				}
			}

			@Override
			public void mouseReleased(MouseEvent e)
			{
				if (e.isPopupTrigger())
				{
					showMenu(e);
				}
			}
		});
	}

	void setLine3(String text)
	{
		if (line3Label != null)
		{
			line3Label.setText(text);
		}
	}

	void setLine3Color(Color color)
	{
		if (line3Label != null)
		{
			line3Label.setForeground(color);
		}
	}

	/** Make a left click do this straight away rather than opening the menu. */
	ItemRow onClick(Runnable action)
	{
		click = action;
		return this;
	}

	ItemRow action(String text, Runnable action)
	{
		JMenuItem item = new JMenuItem(text);
		item.addActionListener(e -> action.run());
		menu.add(item);
		return this;
	}

	private void showMenu(MouseEvent e)
	{
		if (menu.getComponentCount() > 0 && !menu.isVisible())
		{
			menu.show(this, e.getX(), e.getY());
		}
	}
}

package com.moneymaker.ui;

import com.moneymaker.MoneyMakerConfig;
import com.moneymaker.MoneyMakerPlugin;
import com.moneymaker.data.JobResult;
import com.moneymaker.data.PriceBook;
import com.moneymaker.data.Recipe;
import java.awt.BorderLayout;
import java.awt.Color;
import java.awt.Dimension;
import java.awt.GridLayout;
import java.util.ArrayList;
import java.util.Comparator;
import java.util.List;
import java.util.Locale;
import java.util.Set;
import javax.swing.JButton;
import javax.swing.JComboBox;
import javax.swing.JLabel;
import javax.swing.JPanel;
import javax.swing.border.EmptyBorder;
import javax.swing.event.DocumentEvent;
import javax.swing.event.DocumentListener;
import net.runelite.client.game.ItemManager;
import net.runelite.client.ui.ColorScheme;
import net.runelite.client.ui.components.IconTextField;
import net.runelite.client.util.LinkBrowser;

/** Money-making jobs ranked by gp/hr, with what it takes to reach your next level. */
class JobsPanel extends JPanel
{
	private static final String ALL = "All jobs";
	private static final int MAX_ROWS = 150;
	private static final String[] SORTS = {"GP per hour", "Profit each", "Profit to next level", "Fastest to next level"};

	private final MoneyMakerPlugin plugin;
	private final ItemManager itemManager;
	private final IconTextField search = new IconTextField();
	private final JComboBox<String> category = new JComboBox<>();
	private final JComboBox<String> sort = new JComboBox<>(SORTS);
	private final JLabel status = UiUtil.label(" ", UiUtil.MUTED, false);
	private final JPanel list = UiUtil.verticalList();
	/** Rebuild the list a moment after the last keystroke rather than on every one. */
	private final javax.swing.Timer searchDelay = new javax.swing.Timer(250, e -> refresh());

	JobsPanel(MoneyMakerPlugin plugin, ItemManager itemManager)
	{
		this.plugin = plugin;
		this.itemManager = itemManager;

		setLayout(new BorderLayout(0, 4));
		setBackground(ColorScheme.DARK_GRAY_COLOR);

		JPanel controls = new JPanel(new GridLayout(0, 1, 0, 4));
		controls.setBackground(ColorScheme.DARK_GRAY_COLOR);
		controls.setBorder(new EmptyBorder(0, 0, 2, 0));

		search.setIcon(IconTextField.Icon.SEARCH);
		search.setPreferredSize(new Dimension(0, 30));
		search.setBackground(ColorScheme.DARKER_GRAY_COLOR);
		search.setHoverBackgroundColor(ColorScheme.DARK_GRAY_HOVER_COLOR);
		search.getDocument().addDocumentListener(new DocumentListener()
		{
			@Override
			public void insertUpdate(DocumentEvent e)
			{
				searchDelay.restart();
			}

			@Override
			public void removeUpdate(DocumentEvent e)
			{
				searchDelay.restart();
			}

			@Override
			public void changedUpdate(DocumentEvent e)
			{
				searchDelay.restart();
			}
		});
		searchDelay.setRepeats(false);
		controls.add(search);

		Set<String> cats = new java.util.TreeSet<>();
		for (Recipe r : plugin.getRecipes())
		{
			cats.add(r.getCategory());
		}
		category.addItem(ALL);
		for (String c : cats)
		{
			category.addItem(c);
		}
		category.setFocusable(false);
		category.addActionListener(e -> refresh());
		controls.add(category);

		JPanel sortRow = new JPanel(new BorderLayout(4, 0));
		sortRow.setBackground(ColorScheme.DARK_GRAY_COLOR);
		sort.setFocusable(false);
		sort.addActionListener(e -> refresh());
		sortRow.add(sort, BorderLayout.CENTER);
		JButton reload = new JButton("Refresh");
		reload.setFocusable(false);
		reload.addActionListener(e ->
		{
			status.setText("Refreshing...");
			plugin.refreshPricesNow();
		});
		sortRow.add(reload, BorderLayout.EAST);
		controls.add(sortRow);
		controls.add(status);

		add(controls, BorderLayout.NORTH);
		add(UiUtil.scroll(list), BorderLayout.CENTER);
		refresh();
	}

	void refresh()
	{
		list.removeAll();
		PriceBook prices = plugin.getPrices();
		MoneyMakerConfig config = plugin.getConfig();

		if (prices.isEmpty())
		{
			String err = plugin.getPriceError();
			status.setText(err != null ? "Couldn't load prices" : "Loading prices...");
			list.add(UiUtil.emptyState(err != null ? "Couldn't reach the OSRS Wiki price API.<br>" + err : "Fetching prices..."));
			repaintList();
			return;
		}

		String q = search.getText() == null ? "" : search.getText().trim().toLowerCase(Locale.ROOT);
		String cat = (String) category.getSelectedItem();
		boolean loggedIn = false;

		List<JobResult> results = new ArrayList<>();
		for (Recipe r : plugin.getRecipes())
		{
			if (cat != null && !ALL.equals(cat) && !cat.equals(r.getCategory()))
			{
				continue;
			}
			if (!q.isEmpty() && !r.getName().toLowerCase(Locale.ROOT).contains(q))
			{
				continue;
			}
			if (!config.includeMembers() && r.isMembers())
			{
				continue;
			}

			long[] skill = r.hasSkill() ? plugin.getSkill(r.getSkill()) : null;
			loggedIn |= plugin.isLoggedIn();
			int level = skill != null ? (int) skill[0] : 0;
			long xp = skill != null ? skill[1] : -1;
			boolean canDo = missingReq(r) == null;
			if (config.onlyDoable() && !canDo)
			{
				continue;
			}

			JobResult res = JobResult.evaluate(r, prices, config.priceMode(), config.speed(),
				canDo ? level : 0, canDo ? xp : -1, MoneyMakerPlugin.xpForNextLevel(level));
			if (res == null || (config.hideLowVolume() && (res.isLowVolume() || res.isStale())))
			{
				continue;
			}
			results.add(res);
		}

		results.sort(comparator());

		status.setText(results.size() + " jobs · prices " + UiUtil.ago(prices.getUpdatedAt())
			+ (plugin.getPriceError() != null ? " (refresh failed)" : "")
			+ (loggedIn ? "" : " · log in for level info"));

		if (results.isEmpty())
		{
			list.add(UiUtil.emptyState("No jobs match."));
		}
		if (plugin.isIronman())
		{
			list.add(UiUtil.emptyState("Ironman mode: GE prices don't apply to you.<br>Use the <b>Train</b> tab for the fastest route to your next milestone."));
		}
		int shown = 0;
		for (JobResult r : results)
		{
			if (++shown > MAX_ROWS)
			{
				list.add(UiUtil.emptyState("Showing the top " + MAX_ROWS + " of " + results.size()
					+ ".<br>Pick a category or search to see the rest."));
				break;
			}
			UiUtil.addRow(list, row(r));
		}
		repaintList();
	}

	private Comparator<JobResult> comparator()
	{
		switch (Math.max(0, sort.getSelectedIndex()))
		{
			case 1:
				return Comparator.comparingLong(JobResult::getProfitEach).reversed();
			case 2:
				return Comparator.comparingLong((JobResult r) -> r.getNext() != null ? r.getNext().getProfit() : Long.MIN_VALUE).reversed();
			case 3:
				return Comparator.comparingDouble((JobResult r) -> r.getNext() != null ? r.getNext().getHours() : Double.MAX_VALUE);
			default:
				return Comparator.comparingLong(JobResult::getGpPerHour).reversed();
		}
	}

	private ItemRow row(JobResult r)
	{
		Recipe rec = r.getRecipe();
		int icon = r.getOutputLines().isEmpty() ? -1 : r.getOutputLines().get(0).getItemId();
		long gpHr = r.getGpPerHour();

		String line2 = UiUtil.signedGp(r.getProfitEach()) + "/" + unit(rec, 1) + " · " + UiUtil.compact(Math.round(r.getActionsPerHour())) + "/hr"
			+ (r.isLimitCapped() ? " (limit)" : "") + (r.isStale() ? " (old price)" : "");

		String line3;
		Color line3Color = UiUtil.MUTED;
		long[] skill = rec.hasSkill() ? plugin.getSkill(rec.getSkill()) : null;
		Recipe.Req missing = missingReq(rec);
		if (missing != null)
		{
			long[] have = plugin.getSkill(missing.getSkill());
			line3 = "Needs " + missing.getLevel() + " " + pretty(plugin.resolveSkill(missing.getSkill())) + " (you: " + (have != null ? have[0] : "?") + ")";
			line3Color = UiUtil.LOSS;
		}
		else if (!rec.hasSkill())
		{
			line3 = rec.getCategory() + (rec.isMembers() ? " · members" : "");
		}
		else if (r.getNext() != null)
		{
			JobResult.NextLevel n = r.getNext();
			line3 = pretty(plugin.resolveSkill(rec.getSkill())) + " " + n.getTargetLevel() + ": " + UiUtil.compact(n.getActions()) + " " + unit(rec, n.getActions()) + " · "
				+ UiUtil.signedGp(n.getProfit()) + " · " + hours(n.getHours());
		}
		else
		{
			line3 = rec.getLevel() + " " + pretty(plugin.resolveSkill(rec.getSkill())) + (rec.getXp() > 0 ? " · " + num(rec.getXp()) + " xp/" + unit(rec, 1) : " · no xp");
		}

		ItemRow row = new ItemRow(itemManager, icon, rec.getName(), UiUtil.signedGp(gpHr) + "/h", UiUtil.profitColor(gpHr),
			line2, line3, tooltip(r));
		row.setLine3Color(line3Color);
		if (!rec.getUrl().isEmpty())
		{
			row.action("Open wiki guide", () -> LinkBrowser.browse(rec.getUrl()));
		}
		if (!r.getOutputLines().isEmpty())
		{
			int id = r.getOutputLines().get(0).getItemId();
			row.action("Open price chart", () -> LinkBrowser.browse("https://prices.runescape.wiki/osrs/item/" + id));
		}
		return row;
	}

	private String tooltip(JobResult r)
	{
		Recipe rec = r.getRecipe();
		StringBuilder sb = new StringBuilder("<html><b>").append(esc(rec.getName())).append("</b>");
		if (!rec.getReqs().isEmpty())
		{
			sb.append("<br>Needs ");
			for (int i = 0; i < rec.getReqs().size(); i++)
			{
				Recipe.Req q = rec.getReqs().get(i);
				sb.append(i > 0 ? ", " : "").append(q.getLevel()).append(' ').append(pretty(plugin.resolveSkill(q.getSkill())));
			}
		}
		if (rec.hasSkill())
		{
			sb.append("<br>").append(rec.getXp() > 0 ? num(rec.getXp()) + " " + pretty(plugin.resolveSkill(rec.getSkill())) + " xp per " + unit(rec, 1) : "No xp");
		}
		sb.append("<br><br><b>Buy (per ").append(unit(rec, 1)).append(")</b>");
		for (JobResult.Line l : r.getInputLines())
		{
			sb.append("<br>").append(num(l.getQty())).append(" × ").append(esc(l.getItem())).append(" @ ").append(UiUtil.gp(l.getPriceEach()));
		}
		if (rec.getCoinsPerAction() > 0)
		{
			sb.append("<br>+ ").append(num(rec.getCoinsPerAction())).append(" gp in fees/supplies");
		}
		sb.append("<br><b>Get</b>");
		if (rec.getCoinsPerAction() < 0)
		{
			sb.append("<br>").append(num(-rec.getCoinsPerAction())).append(" coins (or untradeable loot valued in coins)");
		}
		int shown = 0;
		for (JobResult.Line l : r.getOutputLines())
		{
			if (++shown > 12)
			{
				sb.append("<br>... and ").append(r.getOutputLines().size() - 12).append(" more drops");
				break;
			}
			sb.append("<br>").append(num(l.getQty())).append(" × ").append(esc(l.getItem())).append(" @ ").append(UiUtil.gp(l.getPriceEach()));
		}
		sb.append("<br>Profit per ").append(unit(rec, 1)).append(" after 2% tax: <b>").append(UiUtil.signedGp(r.getProfitEach())).append("</b>");
		sb.append("<br>~").append(UiUtil.gp(Math.round(r.getActionsPerHour()))).append(" per hour = <b>")
			.append(UiUtil.signedGp(r.getGpPerHour())).append(" gp/hr</b>");
		if (r.isLimitCapped())
		{
			sb.append("<br><i>Slowed by the GE buy limit on ").append(esc(r.getCappedBy())).append("</i>");
		}
		if (r.isLowVolume())
		{
			sb.append("<br><i>Low trade volume: selling may take a while</i>");
		}
		if (r.isStale())
		{
			sb.append("<br><i>Old price: ").append(esc(r.getStaleItem())).append(" hasn't traded in over a day, so this gp/hr may be wrong</i>");
		}

		JobResult.NextLevel n = r.getNext();
		if (n != null)
		{
			sb.append("<br><br><b>To reach ").append(pretty(plugin.resolveSkill(rec.getSkill()))).append(' ').append(n.getTargetLevel()).append("</b> (")
				.append(UiUtil.gp(n.getXpNeeded())).append(" xp)");
			sb.append("<br>").append(UiUtil.gp(n.getActions())).append(' ').append(unit(rec, n.getActions())).append(", about ").append(hours(n.getHours()));
			sb.append("<br>Shopping list:");
			for (JobResult.Line l : n.getShopping())
			{
				sb.append("<br>&nbsp;&nbsp;").append(UiUtil.gp(Math.round(l.getQty()))).append(" × ").append(esc(l.getItem()))
					.append(" = ").append(UiUtil.gp(Math.round(l.getQty() * l.getPriceEach())));
			}
			sb.append("<br>Cash needed: ").append(UiUtil.gp(n.getShoppingCost()));
			sb.append("<br>Profit by the time you level: <b>").append(UiUtil.signedGp(n.getProfit())).append("</b>");
		}
		sb.append("<br><br>Rates are rough estimates; set your speed in the plugin settings.</html>");
		return sb.toString();
	}

	/** First skill requirement you don't meet, or null (also null when logged out). */
	private Recipe.Req missingReq(Recipe r)
	{
		for (Recipe.Req q : r.getReqs())
		{
			long[] have = plugin.getSkill(q.getSkill());
			if (have != null && have[0] < q.getLevel())
			{
				return q;
			}
		}
		return null;
	}

	private static String unit(Recipe r, long n)
	{
		String u = r.getUnit().isEmpty() ? "action" : r.getUnit();
		if (n == 1 || u.equals("min"))
		{
			return u;
		}
		return u.endsWith("sh") || u.endsWith("s") ? u : u + "s";
	}

	/** 3, 2.5, 0.12, 0.0004 */
	private static String num(double v)
	{
		if (v == Math.rint(v) && Math.abs(v) < 1e9)
		{
			return UiUtil.gp((long) v);
		}
		if (Math.abs(v) >= 10)
		{
			return String.format(Locale.ROOT, "%,.1f", v);
		}
		return new java.math.BigDecimal(v).round(new java.math.MathContext(2)).stripTrailingZeros().toPlainString();
	}

	private static String hours(double h)
	{
		if (h <= 0)
		{
			return "-";
		}
		long mins = Math.round(h * 60);
		return mins < 60 ? mins + "m" : (mins / 60) + "h " + (mins % 60) + "m";
	}

	private static String pretty(String skill)
	{
		return skill.charAt(0) + skill.substring(1).toLowerCase(Locale.ROOT);
	}

	private static String esc(String s)
	{
		return s.replace("&", "&amp;").replace("<", "&lt;").replace(">", "&gt;");
	}

	private void repaintList()
	{
		list.revalidate();
		list.repaint();
	}
}

package com.moneymaker.ui;

import com.moneymaker.MoneyMakerPlugin;
import java.awt.BorderLayout;
import java.awt.GridLayout;
import java.awt.event.HierarchyEvent;
import javax.swing.JPanel;
import javax.swing.Timer;
import javax.swing.border.EmptyBorder;
import net.runelite.client.game.ItemManager;
import net.runelite.client.ui.ColorScheme;
import net.runelite.client.ui.FontManager;
import net.runelite.client.ui.PluginPanel;
import net.runelite.client.ui.components.materialtabs.MaterialTab;
import net.runelite.client.ui.components.materialtabs.MaterialTabGroup;

public class MoneyMakerPanel extends PluginPanel
{
	private final JobsPanel jobs;
	private final BossesPanel bosses;
	private final FarmPanel farm;
	private final TrainPanel train;
	private final GoalPanel goal;
	private final MaterialTabGroup tabs;
	private final MaterialTab goalTab;

	private static final int JOBS = 1;
	private static final int TRAIN = 2;
	private static final int FARM = 4;
	private static final int ALL = 8;
	private static final int BOSSES = 16;
	/** How long to wait for XP drops and bank changes to settle before redrawing. */
	private static final int SETTLE_MS = 1000;

	/** What needs redrawing (JOBS, TRAIN, FARM, ALL). Only touched on the Swing thread. */
	private int pending;
	private final Timer settle = new Timer(SETTLE_MS, e -> flush());

	public MoneyMakerPanel(MoneyMakerPlugin plugin, ItemManager itemManager)
	{
		super(false);
		setLayout(new BorderLayout());
		setBackground(ColorScheme.DARK_GRAY_COLOR);
		setBorder(new EmptyBorder(6, 4, 6, 4));

		jobs = new JobsPanel(plugin, itemManager);
		bosses = new BossesPanel(plugin, itemManager);
		farm = new FarmPanel(plugin, itemManager);
		train = new TrainPanel(plugin, itemManager);
		goal = new GoalPanel(plugin, itemManager);

		JPanel display = new JPanel(new BorderLayout());
		display.setBackground(ColorScheme.DARK_GRAY_COLOR);

		tabs = new MaterialTabGroup(display);
		tabs.setLayout(new GridLayout(1, 5, 0, 0));
		tabs.setBorder(new EmptyBorder(0, 0, 8, 0));

		MaterialTab jobsTab = tab(tabs, "Jobs", "Money-making jobs ranked by gp/hr", jobs);
		MaterialTab trainTab = tab(tabs, "Train", "Fastest XP route to your next milestone level", train);
		tab(tabs, "Boss", "Boss gear from cheapest to best, and whether you can fight it", bosses);
		tab(tabs, "Farm", "Best farm runs, bird houses and dailies, with timers", farm);
		goalTab = tab(tabs, "Goal", "What you want, what it costs and the quickest way to pay for it", goal);
		tabs.select(plugin.isIronman() ? trainTab : jobsTab);

		add(tabs, BorderLayout.NORTH);
		add(display, BorderLayout.CENTER);

		settle.setRepeats(false);
		// catch up on anything that changed while the panel was closed
		addHierarchyListener(e ->
		{
			if ((e.getChangeFlags() & HierarchyEvent.SHOWING_CHANGED) != 0 && isShowing())
			{
				flush();
			}
		});
	}

	/** Redraw whatever is waiting, if the panel is on screen. If it isn't, it waits until it is. */
	private void flush()
	{
		if (!isShowing() || pending == 0)
		{
			return;
		}
		int todo = pending;
		pending = 0;
		settle.stop();
		if ((todo & ALL) != 0)
		{
			jobs.refresh();
			bosses.refresh();
			farm.refresh();
			train.refresh();
			goal.refresh();
			return;
		}
		if ((todo & JOBS) != 0)
		{
			jobs.refresh();
		}
		if ((todo & TRAIN) != 0)
		{
			train.refresh();
		}
		if ((todo & FARM) != 0)
		{
			farm.refresh();
		}
		if ((todo & BOSSES) != 0)
		{
			bosses.refresh();
		}
		// levels and coins feed both the boss check and the goal plan
		if ((todo & (JOBS | TRAIN)) != 0)
		{
			bosses.refresh();
			goal.refresh();
		}
	}

	/** Open the Goal tab with this item as the goal. */
	public void showGoal(String item)
	{
		goal.setItem(item);
		tabs.select(goalTab);
	}

	/** Stop the timers when the plugin is turned off. */
	public void shutDown()
	{
		settle.stop();
		farm.stop();
	}

	private static MaterialTab tab(MaterialTabGroup group, String name, String tooltip, JPanel content)
	{
		MaterialTab tab = new MaterialTab(name, group, content);
		tab.setToolTipText(tooltip);
		tab.setFont(FontManager.getRunescapeSmallFont());
		group.addTab(tab);
		return tab;
	}

	/** Prices or settings changed: redraw everything now, or when the panel is next opened. */
	public void refreshAll()
	{
		pending |= ALL;
		flush();
	}

	/** Your items changed. These come in bursts while banking, so wait for them to settle. */
	public void refreshTrain()
	{
		pending |= TRAIN;
		settle.restart();
	}

	/** Your quest progress changed. */
	public void refreshBosses()
	{
		pending |= BOSSES;
		flush();
	}

	public void refreshFarm()
	{
		pending |= FARM;
		flush();
	}

	public void refreshFarmTimers()
	{
		farm.refreshTimers();
	}

	/** Your levels or XP changed. Every XP drop lands here, so wait for them to settle. */
	public void refreshJobs()
	{
		pending |= JOBS | TRAIN;
		settle.restart();
	}
}

package com.moneymaker.ui;

import com.moneymaker.MoneyMakerConfig;
import com.moneymaker.MoneyMakerPlugin;
import com.moneymaker.data.Gear;
import com.moneymaker.data.ItemPrice;
import com.moneymaker.data.PriceBook;
import com.moneymaker.data.Recipe;
import com.moneymaker.data.Training;
import java.awt.BorderLayout;
import java.awt.Color;
import java.awt.GridLayout;
import java.util.ArrayList;
import java.util.Comparator;
import java.util.List;
import java.util.Locale;
import javax.swing.JCheckBox;
import javax.swing.JComboBox;
import javax.swing.JLabel;
import javax.swing.JPanel;
import javax.swing.JSpinner;
import javax.swing.SpinnerNumberModel;
import javax.swing.border.EmptyBorder;
import net.runelite.client.game.ItemManager;
import net.runelite.client.ui.ColorScheme;

/** Fastest way to a milestone level: best method at every level, how long it takes and what you need. */
class TrainPanel extends JPanel
{
	private final MoneyMakerPlugin plugin;
	private final ItemManager itemManager;
	private final JComboBox<String> skill = new JComboBox<>();
	private final JSpinner from = new JSpinner(new SpinnerNumberModel(1, 1, 98, 1));
	private final JComboBox<Target> target = new JComboBox<>();
	private final JCheckBox noSupplies = new JCheckBox("Only methods with no supplies");
	private final JCheckBox intense = new JCheckBox("Include click-intensive methods", true);
	private final JLabel summary = UiUtil.label(" ", Color.WHITE, false);
	private final JPanel list = UiUtil.verticalList();
	private final List<String> skills;
	private boolean updating;
	/** Last skill/level we filled the controls from, so logging in fills them once. */
	private String filledFor = "";

	private static class Target
	{
		final int level;
		final String text;

		Target(int level, String text)
		{
			this.level = level;
			this.text = text;
		}

		@Override
		public String toString()
		{
			return level + " · " + text;
		}
	}

	TrainPanel(MoneyMakerPlugin plugin, ItemManager itemManager)
	{
		this.plugin = plugin;
		this.itemManager = itemManager;
		this.skills = plugin.getTraining().getSkills();
		setLayout(new BorderLayout(0, 4));
		setBackground(ColorScheme.DARK_GRAY_COLOR);

		JPanel controls = new JPanel(new GridLayout(0, 1, 0, 4));
		controls.setBackground(ColorScheme.DARK_GRAY_COLOR);

		for (String s : skills)
		{
			skill.addItem(pretty(s));
		}
		skill.setFocusable(false);
		skill.addActionListener(e ->
		{
			if (!updating)
			{
				fillFromLevel();
				fillTargets();
				refresh();
			}
		});
		controls.add(skill);

		JPanel fromRow = new JPanel(new BorderLayout(4, 0));
		fromRow.setBackground(ColorScheme.DARK_GRAY_COLOR);
		fromRow.add(UiUtil.label("From level", UiUtil.MUTED, false), BorderLayout.WEST);
		fromRow.add(from, BorderLayout.CENTER);
		from.addChangeListener(e ->
		{
			if (!updating)
			{
				fillTargets();
				refresh();
			}
		});
		controls.add(fromRow);

		target.setFocusable(false);
		target.addActionListener(e ->
		{
			if (!updating)
			{
				refresh();
			}
		});
		controls.add(target);

		for (JCheckBox c : new JCheckBox[]{noSupplies, intense})
		{
			c.setBackground(ColorScheme.DARK_GRAY_COLOR);
			c.setFocusable(false);
			c.addActionListener(e -> refresh());
			controls.add(c);
		}
		controls.add(summary);

		add(controls, BorderLayout.NORTH);
		add(UiUtil.scroll(list), BorderLayout.CENTER);

		fillFromLevel();
		fillTargets();
		refresh();
	}

	private String selectedSkill()
	{
		int i = skill.getSelectedIndex();
		return i < 0 || i >= skills.size() ? "" : skills.get(i);
	}

	/** Your level when logged in, else whatever was typed. */
	private void fillFromLevel()
	{
		long[] s = plugin.getSkill(selectedSkill());
		if (s != null)
		{
			updating = true;
			from.setValue((int) Math.max(1, Math.min(98, s[0])));
			updating = false;
		}
	}

	private void fillTargets()
	{
		updating = true;
		Target keep = (Target) target.getSelectedItem();
		target.removeAllItems();
		int fromLvl = (Integer) from.getValue();
		List<Target> ts = new ArrayList<>();
		for (Training.Milestone m : plugin.getTraining().getMilestones(selectedSkill()))
		{
			if (m.getLevel() > fromLvl)
			{
				ts.add(new Target(m.getLevel(), m.getText()));
			}
		}
		if (ts.isEmpty() || ts.get(0).level != fromLvl + 1)
		{
			ts.add(0, new Target(fromLvl + 1, "Next level"));
		}
		if (ts.get(ts.size() - 1).level != 99)
		{
			ts.add(new Target(99, "Skill cape"));
		}
		Target select = ts.size() > 1 && ts.get(0).text.equals("Next level") ? ts.get(1) : ts.get(0);
		for (Target t : ts)
		{
			target.addItem(t);
			if (keep != null && keep.level == t.level)
			{
				select = t;
			}
		}
		target.setSelectedItem(select);
		updating = false;
	}

	/** Called when skills or prices change. */
	void refresh()
	{
		String sk = selectedSkill();
		long[] mine = plugin.getSkill(sk);
		if (mine != null && !filledFor.equals(sk + mine[0]))
		{
			filledFor = sk + mine[0];
			fillFromLevel();
			fillTargets();
		}

		list.removeAll();
		Target t = (Target) target.getSelectedItem();
		if (sk.isEmpty() || t == null)
		{
			repaintList();
			return;
		}
		MoneyMakerConfig config = plugin.getConfig();
		boolean iron = plugin.isIronman();
		int fromLvl = (Integer) from.getValue();
		long fromXp = mine != null && mine[0] == fromLvl ? mine[1] : Training.xpForLevel(fromLvl);

		Training.Filter filter = new Training.Filter();
		filter.ironman = iron;
		filter.members = config.includeMembers();
		filter.intense = intense.isSelected();
		Training training = plugin.getTraining();
		filter.noSupplies = noSupplies.isSelected();
		List<Training.Step> steps = training.plan(sk, fromXp, t.level, filter);

		double hours = 0;
		double days = 0;
		for (Training.Step s : steps)
		{
			hours += s.getHours();
			days += s.getDays();
		}
		long xpNeeded = Training.xpForLevel(t.level) - fromXp;
		summary.setText("<html><b>" + pretty(sk) + " " + fromLvl + " → " + t.level + "</b> (" + esc(t.text) + ")<br>"
			+ UiUtil.gp(xpNeeded) + " xp · about " + time(hours) + (days > 0 ? " of runs over ~" + Math.round(days) + " days" : "")
			+ (iron ? "<br><i>Ironman mode: shows what to gather</i>" : "") + "</html>");

		addGear(sk, mine != null ? (int) mine[0] : fromLvl, mine != null);

		list.add(UiUtil.header("Fastest route"));
		if (steps.isEmpty())
		{
			list.add(UiUtil.emptyState("No methods match your filters at this level."));
		}
		for (Training.Step s : steps)
		{
			UiUtil.addRow(list, stepRow(s, iron));
		}

		boolean hasRuns = false;
		for (Training.Method m : training.getMethods(sk))
		{
			hasRuns |= m.getCycleMinutes() > 0;
		}
		if (hasRuns)
		{
			Training.Filter runs = new Training.Filter();
			runs.members = filter.members;
			runs.timedOnly = true;
			List<Training.Step> runSteps = training.plan(sk, fromXp, t.level, runs);
			list.add(UiUtil.header("Or with farm runs (best tree each level)"));
			for (Training.Step s : runSteps)
			{
				UiUtil.addRow(list, stepRow(s, iron));
			}
			list.add(UiUtil.emptyState("Tip: do fruit tree, hardwood and herb runs at the same time to level faster."));
		}

		list.add(UiUtil.header("All methods at level " + fromLvl));
		List<Training.Method> all = new ArrayList<>(training.getMethods(sk));
		all.sort(Comparator.comparing((Training.Method m) -> m.getLevel() > fromLvl)
			.thenComparing(Comparator.comparingDouble((Training.Method m) -> m.xpPerHour(Math.max(fromLvl, m.getLevel()))).reversed()));
		for (Training.Method m : all)
		{
			if (!filter.members && m.isMembers())
			{
				continue;
			}
			UiUtil.addRow(list, methodRow(m, fromLvl, iron));
		}
		repaintList();
	}

	private ItemRow stepRow(Training.Step s, boolean iron)
	{
		Training.Method m = s.getMethod();
		String title = "Lv " + s.getFromLevel() + "–" + s.getToLevel() + ": " + m.getName();
		String line2 = "~" + UiUtil.compact(Math.round(m.xpPerHour(s.getFromLevel()))) + " xp/h · " + UiUtil.compact(Math.round(s.getXp())) + " xp"
			+ (s.getActions() > 0 ? " · " + UiUtil.gp(s.getActions()) + " " + plural(m.getUnit(), s.getActions()) : "");
		String line3 = supplies(m, s.getActions(), iron);
		String value = s.getDays() > 0 ? "~" + Math.round(s.getDays()) + "d" : time(s.getHours());
		ItemRow row = new ItemRow(itemManager, icon(m), title, value, Color.WHITE, line2, line3, tooltip(m, s, iron));
		row.setLine3Color(line3.startsWith("Needs") ? UiUtil.LOSS : UiUtil.MUTED);
		return row;
	}

	private ItemRow methodRow(Training.Method m, int fromLvl, boolean iron)
	{
		boolean locked = m.getLevel() > fromLvl;
		double rate = m.xpPerHour(Math.max(fromLvl, m.getLevel()));
		String line2 = (locked ? "Unlocks at " + m.getLevel() : "Level " + m.getLevel() + "+")
			+ (m.isMembers() ? "" : " · F2P") + (m.isIntense() ? " · intense" : "")
			+ (m.getNeeds().isEmpty() ? " · no supplies" : "");
		String line3 = !m.getRequirements().isEmpty() ? "Needs: " + m.getRequirements() : m.getNote();
		ItemRow row = new ItemRow(itemManager, icon(m), m.getName(), UiUtil.compact(Math.round(rate)) + "/h",
			locked ? UiUtil.MUTED : UiUtil.PROFIT, line2, line3.isEmpty() ? " " : line3, tooltip(m, null, iron));
		row.setLine3Color(UiUtil.MUTED);
		return row;
	}

	/** Your tools, outfit and useful items for the skill, from your bag, worn gear and bank. */
	private void addGear(String sk, int level, boolean loggedIn)
	{
		List<Gear.Line> lines = plugin.getGear().check(sk, level, plugin.getOwned());
		if (lines.isEmpty())
		{
			return;
		}
		list.add(UiUtil.header("Your gear for " + pretty(sk)));
		if (!loggedIn)
		{
			list.add(UiUtil.emptyState("Log in so I can check your bag, worn gear and bank."));
			return;
		}
		JPanel box = new JPanel(new GridLayout(0, 1, 0, 2));
		box.setBackground(ColorScheme.DARKER_GRAY_COLOR);
		box.setBorder(new EmptyBorder(6, 6, 6, 6));
		for (Gear.Line l : lines)
		{
			Color c = l.getKind() == Gear.Line.Kind.GOOD ? UiUtil.PROFIT
				: l.getKind() == Gear.Line.Kind.UPGRADE ? new Color(255, 200, 70)
				: l.getKind() == Gear.Line.Kind.MISSING ? UiUtil.MUTED : Color.WHITE;
			String mark = l.getKind() == Gear.Line.Kind.GOOD ? "✔ " : l.getKind() == Gear.Line.Kind.UPGRADE ? "▲ " : l.getKind() == Gear.Line.Kind.MISSING ? "✘ " : "• ";
			JLabel label = UiUtil.label("<html><body style='width:165px'>" + mark + esc(l.getText()) + "</body></html>", c, false);
			box.add(label);
		}
		if (!plugin.isBankSeen())
		{
			box.add(UiUtil.label("<html><i>Open your bank once so I can include it.</i></html>", UiUtil.MUTED, false));
		}
		UiUtil.addRow(list, box);
	}

	/** "Gather: 2,000 × Feather" (ironman) or "Buy: ... ≈ 40k gp". */
	private String supplies(Training.Method m, long actions, boolean iron)
	{
		if (m.getNeeds().isEmpty() || actions <= 0)
		{
			if (!m.getRequirements().isEmpty())
			{
				return "Needs: " + m.getRequirements();
			}
			return m.getNote().isEmpty() ? " " : m.getNote();
		}
		StringBuilder sb = new StringBuilder(iron ? "Gather: " : "Buy: ");
		java.util.Map<String, Gear.Owned> owned = plugin.getOwned();
		long cost = 0;
		PriceBook prices = plugin.getPrices();
		for (int i = 0; i < m.getNeeds().size(); i++)
		{
			Recipe.Stack st = m.getNeeds().get(i);
			long qty = (long) Math.ceil(st.getQty() * actions);
			sb.append(i > 0 ? ", " : "").append(UiUtil.compact(qty)).append(' ').append(st.getItem());
			Gear.Owned have = Gear.find(owned, st.getItem());
			if (have != null)
			{
				sb.append(" (have ").append(UiUtil.compact(have.getQty())).append(')');
			}
			ItemPrice p = prices.get(st.getItem());
			if (p != null)
			{
				cost += qty * p.buyPrice(plugin.getConfig().priceMode());
			}
		}
		if (!iron && cost > 0)
		{
			sb.append(" ≈ ").append(UiUtil.compact(cost)).append(" gp");
		}
		return sb.toString();
	}

	private String tooltip(Training.Method m, Training.Step s, boolean iron)
	{
		StringBuilder sb = new StringBuilder("<html><b>").append(esc(m.getName())).append("</b>");
		sb.append("<br>From level ").append(m.getLevel()).append(m.isMembers() ? " (members)" : " (F2P)");
		if (m.getXpEach() > 0)
		{
			sb.append("<br>").append(num(m.getXpEach())).append(" xp per ").append(m.getUnit());
		}
		sb.append("<br>~").append(UiUtil.gp(Math.round(m.xpPerHour(m.getLevel())))).append(" xp/h at ").append(m.getLevel())
			.append(", ~").append(UiUtil.gp(Math.round(m.xpPerHour(99)))).append(" at 99");
		if (!m.getRequirements().isEmpty())
		{
			sb.append("<br>Needs: ").append(esc(m.getRequirements()));
		}
		if (s != null && s.getActions() > 0)
		{
			long a = s.getActions();
			if (!m.getNeeds().isEmpty())
			{
				sb.append("<br><br><b>").append(iron ? "Gather" : "Buy").append(" for this stretch</b>");
				for (Recipe.Stack st : m.getNeeds())
				{
					sb.append("<br>").append(UiUtil.gp((long) Math.ceil(st.getQty() * a))).append(" × ").append(esc(st.getItem()));
				}
			}
			if (!m.getGives().isEmpty())
			{
				sb.append("<br><b>You'll end up with</b>");
				for (Recipe.Stack st : m.getGives())
				{
					sb.append("<br>").append(UiUtil.gp((long) Math.floor(st.getQty() * a))).append(" × ").append(esc(st.getItem()));
				}
			}
			if (m.getCycleMinutes() > 0)
			{
				sb.append("<br><br>").append(UiUtil.gp(a)).append(" runs, one every ").append(time(m.getCycleMinutes() / 60.0))
					.append(" (~").append(Math.round(s.getDays())).append(" days)");
			}
		}
		if (!m.getNote().isEmpty())
		{
			sb.append("<br><br><i>").append(esc(m.getNote())).append("</i>");
		}
		sb.append("<br><br>Rates are typical estimates from OSRS Wiki training guides.</html>");
		return sb.toString();
	}

	private int icon(Training.Method m)
	{
		PriceBook prices = plugin.getPrices();
		for (List<Recipe.Stack> l : List.of(m.getGives(), m.getNeeds()))
		{
			for (Recipe.Stack st : l)
			{
				ItemPrice p = prices.get(st.getItem());
				if (p != null)
				{
					return p.getId();
				}
			}
		}
		return -1;
	}

	private static String plural(String unit, long n)
	{
		if (n == 1 || unit.endsWith("s") || unit.contains(" "))
		{
			return unit;
		}
		return unit.endsWith("sh") ? unit + "es" : unit + "s";
	}

	private static String time(double hours)
	{
		if (hours <= 0)
		{
			return "-";
		}
		long mins = Math.round(hours * 60);
		if (mins < 60)
		{
			return mins + "m";
		}
		return mins < 6000 ? (mins / 60) + "h " + (mins % 60) + "m" : (mins / 60) + "h";
	}

	private static String num(double v)
	{
		return v == Math.rint(v) ? UiUtil.gp((long) v) : String.format(Locale.ROOT, "%.1f", v);
	}

	private static String pretty(String skill)
	{
		return skill.charAt(0) + skill.substring(1).toLowerCase(Locale.ROOT);
	}

	private static String esc(String s)
	{
		return s.replace("&", "&amp;").replace("<", "&lt;").replace(">", "&gt;");
	}

	private void repaintList()
	{
		list.revalidate();
		list.repaint();
	}
}

package com.moneymaker.ui;

import java.awt.BorderLayout;
import java.awt.Color;
import java.awt.Component;
import java.awt.Dimension;
import java.awt.Rectangle;
import javax.swing.BorderFactory;
import javax.swing.Box;
import javax.swing.BoxLayout;
import javax.swing.JComponent;
import javax.swing.JLabel;
import javax.swing.JPanel;
import javax.swing.JScrollPane;
import javax.swing.Scrollable;
import javax.swing.ScrollPaneConstants;
import javax.swing.SwingConstants;
import javax.swing.border.EmptyBorder;
import net.runelite.client.ui.ColorScheme;
import net.runelite.client.ui.FontManager;
import net.runelite.client.util.QuantityFormatter;

final class UiUtil
{
	static final Color PROFIT = ColorScheme.PROGRESS_COMPLETE_COLOR;
	static final Color LOSS = ColorScheme.PROGRESS_ERROR_COLOR;
	static final Color MUTED = ColorScheme.LIGHT_GRAY_COLOR;

	private UiUtil()
	{
	}

	/** Exact with commas under 10m, compact above. */
	static String gp(long v)
	{
		return Math.abs(v) >= 10_000_000 ? QuantityFormatter.quantityToStackSize(v) : QuantityFormatter.formatNumber(v);
	}

	static String compact(long v)
	{
		return QuantityFormatter.quantityToStackSize(v);
	}

	static String signedGp(long v)
	{
		return (v > 0 ? "+" : "") + gp(v);
	}

	static Color profitColor(long v)
	{
		return v > 0 ? PROFIT : v < 0 ? LOSS : MUTED;
	}

	static String duration(long ms)
	{
		long s = Math.max(0, ms / 1000);
		long h = s / 3600;
		long m = (s % 3600) / 60;
		if (h > 0)
		{
			return h + "h " + m + "m";
		}
		if (m > 0)
		{
			return m + "m " + (s % 60) + "s";
		}
		return (s % 60) + "s";
	}

	static String ago(long epochMs)
	{
		long ms = System.currentTimeMillis() - epochMs;
		if (ms < 60_000)
		{
			return "just now";
		}
		long m = ms / 60_000;
		if (m < 60)
		{
			return m + "m ago";
		}
		long h = m / 60;
		if (h < 48)
		{
			return h + "h ago";
		}
		return (h / 24) + "d ago";
	}

	static JLabel label(String text, Color color, boolean bold)
	{
		JLabel l = new JLabel(text);
		l.setForeground(color);
		l.setFont(bold ? FontManager.getRunescapeBoldFont() : FontManager.getRunescapeSmallFont());
		return l;
	}

	static JLabel header(String text)
	{
		JLabel l = label(text, Color.WHITE, true);
		l.setBorder(new EmptyBorder(8, 2, 4, 2));
		l.setAlignmentX(Component.LEFT_ALIGNMENT);
		return l;
	}

	static JLabel emptyState(String text)
	{
		JLabel l = label("<html><div style='text-align:center'>" + text + "</div></html>", MUTED, false);
		l.setHorizontalAlignment(SwingConstants.CENTER);
		l.setBorder(new EmptyBorder(20, 8, 20, 8));
		l.setAlignmentX(Component.LEFT_ALIGNMENT);
		return l;
	}

	/** Vertical list that doesn't stretch its rows. */
	static JPanel verticalList()
	{
		JPanel p = new JPanel();
		p.setLayout(new BoxLayout(p, BoxLayout.Y_AXIS));
		p.setBackground(ColorScheme.DARK_GRAY_COLOR);
		return p;
	}

	static void addRow(JPanel list, JComponent row)
	{
		row.setAlignmentX(Component.LEFT_ALIGNMENT);
		row.setMaximumSize(new Dimension(Integer.MAX_VALUE, row.getPreferredSize().height));
		list.add(row);
		list.add(Box.createRigidArea(new Dimension(0, 4)));
	}

	static JScrollPane scroll(JPanel list)
	{
		// Track the viewport width so long rows shrink instead of getting clipped on the right.
		JPanel wrapper = new ScrollablePanel();
		wrapper.setBackground(ColorScheme.DARK_GRAY_COLOR);
		wrapper.add(list, BorderLayout.NORTH);

		JScrollPane scroll = new JScrollPane(wrapper);
		scroll.setHorizontalScrollBarPolicy(ScrollPaneConstants.HORIZONTAL_SCROLLBAR_NEVER);
		scroll.setBorder(BorderFactory.createEmptyBorder());
		scroll.getVerticalScrollBar().setUnitIncrement(16);
		scroll.setBackground(ColorScheme.DARK_GRAY_COLOR);
		return scroll;
	}

	private static class ScrollablePanel extends JPanel implements Scrollable
	{
		ScrollablePanel()
		{
			super(new BorderLayout());
		}

		@Override
		public Dimension getPreferredScrollableViewportSize()
		{
			return getPreferredSize();
		}

		@Override
		public int getScrollableUnitIncrement(Rectangle visibleRect, int orientation, int direction)
		{
			return 16;
		}

		@Override
		public int getScrollableBlockIncrement(Rectangle visibleRect, int orientation, int direction)
		{
			return visibleRect.height;
		}

		@Override
		public boolean getScrollableTracksViewportWidth()
		{
			return true;
		}

		@Override
		public boolean getScrollableTracksViewportHeight()
		{
			return false;
		}
	}
}

package com.moneymaker;

import java.util.ArrayList;
import java.util.Arrays;
import java.util.List;
import net.runelite.client.RuneLite;
import net.runelite.client.externalplugins.ExternalPluginManager;

/** Launches RuneLite with this plugin loaded. Run main in IntelliJ. */
public class MoneyMakerPluginTest
{
	public static void main(String[] args) throws Exception
	{
		// RuneLite's developer mode needs assertions on (-ea). If they're off, relaunch with them on.
		boolean assertionsOn = false;
		assert assertionsOn = true;
		if (!assertionsOn)
		{
			String java = ProcessHandle.current().info().command().orElse("java");
			List<String> cmd = new ArrayList<>(Arrays.asList(java, "-ea",
				"-cp", System.getProperty("java.class.path"), MoneyMakerPluginTest.class.getName()));
			cmd.addAll(Arrays.asList(args));
			Process process = new ProcessBuilder(cmd).inheritIO().start();
			System.exit(process.waitFor());
			return;
		}

		ExternalPluginManager.loadBuiltin(MoneyMakerPlugin.class);
		RuneLite.main(args);
	}
}

package com.moneymaker.data;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNotNull;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;

import java.io.ByteArrayInputStream;
import java.io.InputStream;
import java.nio.charset.StandardCharsets;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import org.junit.Test;

/** Checks the maths and the data files without needing the game running. */
public class LedgerDataTest
{
	private static final long NOW = 1_800_000_000_000L;

	private static InputStream text(String s)
	{
		return new ByteArrayInputStream(s.getBytes(StandardCharsets.UTF_8));
	}

	private static InputStream file(String name)
	{
		InputStream in = Recipe.class.getResourceAsStream("../" + name);
		assertNotNull("missing " + name, in);
		return in;
	}

	private static PriceBook book(ItemPrice... items)
	{
		Map<String, ItemPrice> m = new HashMap<>();
		for (ItemPrice p : items)
		{
			m.put(PriceBook.key(p.getName()), p);
		}
		return new PriceBook(m, NOW);
	}

	/** An item that traded a moment ago at one price. */
	private static ItemPrice item(int id, String name, long price)
	{
		return new ItemPrice(id, name, 0, price, price, price, price, 100_000, NOW / 1000);
	}

	@Test
	public void taxIsTwoPercentRoundedDownAndCapped()
	{
		assertEquals(0, GeTax.perItem(1, "Thing", 49));
		assertEquals(1, GeTax.perItem(1, "Thing", 50));
		assertEquals(1, GeTax.perItem(1, "Thing", 99));
		assertEquals(2, GeTax.perItem(1, "Thing", 100));
		assertEquals(5_000_000, GeTax.perItem(1, "Thing", 2_000_000_000L));
	}

	@Test
	public void exemptItemsPayNoTax()
	{
		assertEquals(0, GeTax.perItem(GeTax.BOND_ID, "Old school bond", 15_000_000));
		assertEquals(0, GeTax.perItem(558, "Mind rune", 1_000));
		assertEquals(0, GeTax.perItem(1, " LOBSTER ", 1_000));
		assertEquals(0, GeTax.perItem(1, "Teleport to house (tablet)", 1_000));
		assertEquals(20, GeTax.perItem(1, "Shark", 1_000));
		assertEquals(20, GeTax.perItem(1, null, 1_000));
	}

	@Test
	public void recipeLineIsParsed() throws Exception
	{
		List<Recipe> list = Recipe.load(text(
			"# comment\n"
				+ "Herblore|Clean grimy guam leaf|HERBLORE|3|1|5000|0|Grimy guam leaf*1|Guam leaf*1|2.5\n"
				+ "Combat|Kill thing|MELEE|70|1|30|-100|Shark*2|Bones*1;Rare*0.01|300|SLAYER:75;MELEE:70|kill|https://example.org\n"));
		assertEquals(2, list.size());
		Recipe kill = list.get(1);
		assertEquals(2, kill.getReqs().size());
		assertEquals("SLAYER", kill.getReqs().get(1).getSkill());
		assertEquals(0.01, kill.getOutputs().get(1).getQty(), 1e-9);
		assertEquals("kill", kill.getUnit());
	}

	@Test
	public void aBadLineIsSkippedNotFatal() throws Exception
	{
		List<Recipe> list = Recipe.load(text(
			"Herblore|Broken|HERBLORE|three|1|5000|0|A*1|B*1|2.5\n"
				+ "Herblore|No star|HERBLORE|3|1|5000|0|A|B*1|2.5\n"
				+ "Herblore|Good|HERBLORE|3|1|5000|0|A*1|B*1|2.5\n"));
		assertEquals(1, list.size());
		assertEquals("Good", list.get(0).getName());
	}

	@Test
	public void jobProfitIsAfterTaxAndBuyLimit() throws Exception
	{
		Recipe r = Recipe.load(text("Test|Make B|NONE|1|0|1000|0|A*1|B*1|0\n")).get(0);
		ItemPrice a = new ItemPrice(1, "A", 400, 100, 100, 100, 100, 100_000, NOW / 1000);
		JobResult res = JobResult.evaluate(r, book(a, item(2, "B", 1_000)), PriceMode.INSTANT, 100, 0, -1, -1);
		assertNotNull(res);
		// sell 1000, less 2% tax (20), less 100 to buy
		assertEquals(880, res.getProfitEach());
		// a limit of 400 per 4 hours means 100 an hour, not the 1000 the recipe allows
		assertTrue(res.isLimitCapped());
		assertEquals(88_000, res.getGpPerHour());
		assertFalse(res.isStale());
	}

	@Test
	public void exemptProductIsNotTaxed() throws Exception
	{
		Recipe r = Recipe.load(text("Test|Cook lobster|NONE|1|0|1000|0|Raw lobster*1|Lobster*1|0\n")).get(0);
		JobResult res = JobResult.evaluate(r, book(item(1, "Raw lobster", 100), item(2, "Lobster", 1_000)),
			PriceMode.INSTANT, 100, 0, -1, -1);
		assertEquals(900, res.getProfitEach());
	}

	@Test
	public void priceWithNoTradeForADayIsFlagged() throws Exception
	{
		Recipe r = Recipe.load(text("Test|Make B|NONE|1|0|1000|0|A*1|B*1|0\n")).get(0);
		long twoDaysAgo = NOW / 1000 - 2 * 24 * 3600;
		ItemPrice old = new ItemPrice(2, "B", 0, 1_000, 1_000, 0, 0, 0, twoDaysAgo);
		JobResult res = JobResult.evaluate(r, book(item(1, "A", 100), old), PriceMode.INSTANT, 100, 0, -1, -1);
		assertTrue(res.isStale());
		assertEquals("B", res.getStaleItem());

		// an hour-old trade with nothing in the last hour is quiet, not stale
		ItemPrice quiet = new ItemPrice(2, "B", 0, 1_000, 1_000, 0, 0, 0, NOW / 1000 - 3600);
		assertFalse(JobResult.evaluate(r, book(item(1, "A", 100), quiet), PriceMode.INSTANT, 100, 0, -1, -1).isStale());
	}

	@Test
	public void missingPriceMeansNoResult() throws Exception
	{
		Recipe r = Recipe.load(text("Test|Make B|NONE|1|0|1000|0|A*1|B*1|0\n")).get(0);
		assertNull(JobResult.evaluate(r, book(item(1, "A", 100)), PriceMode.INSTANT, 100, 0, -1, -1));
	}

	@Test
	public void shippedDataFilesAllLoad() throws Exception
	{
